/* ═══════════════════════════════════════════════════════════════════════════
   PASTE 1 of 4 — two new render functions.

   Insert both immediately BEFORE the line:

       /* ── Guidepagina per champion ────────────────────────────────────── */

   i.e. just above `const slugVan = ...` (~line 686). They must sit after `T`
   is defined (~line 662) and after tierFor / bar / wrClass / iconOf, all of
   which are module-level and already above that point.
   ═══════════════════════════════════════════════════════════════════════════ */

/**
 * De tier-lijst in de held: het product zelf, boven de vouw.
 *
 * Er stond een screenshot. Die noemde in zijn eigen titelbalk 111.728 games
 * terwijl de pagina 125.096 zegt, liet "In the lobby" zien en een Wood IV-badge,
 * en bevatte geen enkel cijfer dat AllMid zelf berekent. Een bezoeker die niets
 * van ons weet zag dus geen data, geen product en een tegenspraak.
 *
 * Hier staat in plaats daarvan de echte top vijf per lane, uit champions.json,
 * met de sample size aan elke regel vast. Mid staat open: het merk heet AllMid,
 * en de mid-lijst is de vreemdste van de vijf -- Blitzcrank op twee is precies
 * de regel die iemand laat stoppen met scrollen.
 *
 * Alle vijf de panelen staan in de HTML. JavaScript wisselt alleen `hidden`;
 * zonder JavaScript blijft mid gewoon staan.
 */
function heldTier() {
  const OPEN = "MIDDLE";

  const rijen = (lane) =>
    tierFor(lane)
      .slice(0, 5)
      .map(
        (e, i) => `
          <li>
            <a href="champion/${slugVan(e.naam)}.html">
              <span class="ht-rang">${i + 1}</span>
              <img src="${iconOf(e.baseId)}" alt="" width="128" height="128" loading="lazy" />
              <span class="ht-naam">${esc(e.naam)}</span>
              <span class="ht-balk" aria-hidden="true"><i style="width:${bar(e.winrate).toFixed(1)}%"></i></span>
              <span class="ht-wr ${wrClass(e.winrate)}">${pct(e.winrate)}<small>%</small></span>
              <span class="ht-games">${n(e.games)}<small>games</small></span>
            </a>
          </li>`,
      )
      .join("");

  const tabs = LANES.map(
    ({ key, label }) =>
      `<button type="button" role="tab" id="ht-tab-${key}" aria-controls="ht-pane-${key}"` +
      ` aria-selected="${key === OPEN}" tabindex="${key === OPEN ? 0 : -1}" data-ht="${key}">${esc(label)}</button>`,
  ).join("");

  const panes = LANES.map(
    ({ key, label }) =>
      `<ol class="ht-pane" id="ht-pane-${key}" role="tabpanel" aria-labelledby="ht-tab-${key}"` +
      ` aria-label="${esc(label)} top five"${key === OPEN ? "" : " hidden"}>${rijen(key)}</ol>`,
  ).join("");

  return `<div class="held-tier rise" id="ht">
    <div class="ht-kop">
      <p class="ht-titel">Classic tier list <span>&mdash; live</span></p>
      <div class="ht-lanes" role="tablist" aria-label="Lane">${tabs}</div>
    </div>
    ${panes}
    <div class="ht-voet">
      <span>Top 5 by win rate &middot; smoothed <code>(wins&nbsp;+&nbsp;10)&nbsp;/&nbsp;(games&nbsp;+&nbsp;20)</code> &middot; min. 100 games</span>
      <a href="classic.html#tiers">All 63, all five lanes &rarr;</a>
    </div>
  </div>
<script>
(function () {
  var wrap = document.getElementById("ht");
  if (!wrap) return;
  var tabs = [].slice.call(wrap.querySelectorAll("[data-ht]"));
  function kies(key) {
    tabs.forEach(function (t) {
      var aan = t.dataset.ht === key;
      t.setAttribute("aria-selected", aan ? "true" : "false");
      t.tabIndex = aan ? 0 : -1;
      var p = document.getElementById("ht-pane-" + t.dataset.ht);
      if (p) p.hidden = !aan;
    });
  }
  wrap.addEventListener("click", function (e) {
    var b = e.target && e.target.closest ? e.target.closest("[data-ht]") : null;
    if (b) kies(b.dataset.ht);
  });
  // Pijltjes horen bij een tablist; zonder dit is hij met toetsenbord halfbakken.
  wrap.addEventListener("keydown", function (e) {
    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
    var i = tabs.indexOf(document.activeElement);
    if (i < 0) return;
    e.preventDefault();
    var volgende = tabs[(i + (e.key === "ArrowRight" ? 1 : tabs.length - 1)) % tabs.length];
    volgende.focus();
    kies(volgende.dataset.ht);
  });
})();
<\/script>`;
}

/**
 * Drie cijfers onder de knoppen, plus de zin over sample size als onderschrift.
 *
 * Die zin stond in de lede, op plek vier, als bewering. Hier staat hij naast
 * drie getallen die je kunt natellen -- dan is het geen bewering meer.
 */
function heldBewijs() {
  const cel = (waarde, label) => `<div><b>${waarde}</b><span>${label}</span></div>`;
  return `<div class="held-bewijs">
    ${cel(n(T.games), "Classic games")}
    ${cel(n(T.players), "Players seen")}
    ${cel(n(T.playerRows), "Player slots counted")}
    <p class="hb-noot">
      ${DATE(T.eersteGame)} &ndash; ${DATE(T.laatsteGame)} &middot; patch ${T.patches.join(" &amp; ")}.
      Every number here carries the games behind it &mdash; a win rate without a sample size is just
      a number that looks like an answer.
    </p>
  </div>`;
}


/* ═══════════════════════════════════════════════════════════════════════════
   PASTE 2 of 4 — the hero itself, inside leaguePagina().

   REPLACE this whole block (the copy column and the image column):

       <div class="wrap">
         <div class="rise">
           <p class="eyebrow">Free &middot; Open source &middot; MIT &middot; Windows</p>
           <h1>Everything you need <em>mid-game</em>, and nothing you have to take on faith.</h1>
           ... through ...
           <p class="cta-note">Windows 10 &amp; 11 &middot; no account &middot; no telemetry</p>
         </div>
         <div class="lol-held-beeld rise">${heldBeeld}</div>
       </div>

   with the block below. Leave the surrounding <section class="lol-held"> and
   its .lol-held-dek untouched.
   ═══════════════════════════════════════════════════════════════════════════ */

  <div class="wrap">
    <div class="rise">
      <p class="eyebrow">League of Legends &middot; Classic &middot; patch ${T.patches.join(" &amp; ")}</p>
      <h1>Nobody counts League Classic. <em>So we counted ${n(T.games)} games.</em></h1>
      <p class="lede">
        Lane tier lists, builds and counters from a data set that did not exist until we recorded
        it &mdash; Riot&rsquo;s API does not carry Classic. Plus a desktop app that sets your
        masteries in champion select and puts objective timers on top of the game.
      </p>
      <div class="cta-row">
        <a class="btn btn-primary" href="https://github.com/allmidgg/desktop/releases/latest/download/AllMid-Setup.exe">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3v12" /><path d="m7 11 5 5 5-5" /><path d="M4 20h16" /></svg>
          Download for Windows
        </a>
        <a class="btn btn-ghost" href="classic.html#tiers">See the data first</a>
      </div>
      ${heldBewijs()}
      <p class="cta-note">Windows 10 &amp; 11 &middot; no account &middot; no telemetry &middot; MIT</p>
    </div>
    ${heldTier()}
  </div>


/* ═══════════════════════════════════════════════════════════════════════════
   PASTE 3 of 4 — rehome the screenshot instead of deleting it.

   `heldBeeld` (declared ~line 1049 in leaguePagina) is now unused. Do not
   delete it: it is the only picture of the product that exists. Move it into
   the #app section, where it is context for "six things it does" rather than
   the site's opening claim.

   In the #app section, find:

       <div class="kenmerken">${KENMERKEN.map(kenmerkBlok).join("")}</div>

   and insert directly ABOVE it:
   ═══════════════════════════════════════════════════════════════════════════ */

    <div class="lol-held-beeld app-beeld rise">${heldBeeld}</div>
    <p class="app-beeld-noot">The Live tab, watching the client. Recorded-game count shown in the
      title bar is whatever that machine had synced at the time.</p>


/* ═══════════════════════════════════════════════════════════════════════════
   PASTE 4 of 4 — put absence after evidence.

   In leaguePagina(), the line

       ${modusBalk()}

   currently sits directly under the hero, so the second thing a stranger reads
   is four chips saying "no data yet". CUT that line from there and PASTE it
   directly after the closing </section> of:

       <section class="band" id="classic-spot">

   Same markup, same honesty, 1500px later.
   ═══════════════════════════════════════════════════════════════════════════ */

css:
/* ── Hero tier panel (.held-tier) ────────────────────────────────────────────
   Vervangt de screenshot in de rechterkolom van de held. Staat op het deel van
   de achtergrond waar de scrim al doorlaat, dus hij brengt zijn eigen dekking
   mee -- anders leest de splash-art door de tabel heen. */
.held-tier {
  position: relative;
  border-radius: var(--radius);
  border: 1px solid var(--line-lit);
  background: #0a0c15;
  box-shadow: var(--lift-2), 0 8px 24px -16px rgba(0, 0, 0, 0.8);
  overflow: hidden;
}
@supports (backdrop-filter: blur(2px)) {
  .held-tier { background: rgba(10, 12, 21, 0.94); backdrop-filter: blur(10px) saturate(115%); }
}
.held-tier::before {
  content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none;
  box-shadow: inset 0 1px 0 rgba(244, 224, 166, 0.16), inset 0 0 0 1px rgba(255, 255, 255, 0.02);
}

.ht-kop {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between;
  gap: 0.6rem 1rem;
  padding: 0.85rem clamp(0.8rem, 2vw, 1.15rem);
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(231, 199, 110, 0.05), transparent);
}
.ht-titel {
  margin: 0; font-family: var(--mono); font-size: 0.7rem; font-weight: 700;
  letter-spacing: 0.14em; text-transform: uppercase; color: var(--ink);
}
/* Eén levend puntje. Het zegt "dit rekent", niet "dit is een plaatje". */
.ht-titel span { color: var(--gold); font-weight: 500; }
.ht-titel span::before {
  content: ""; display: inline-block; width: 6px; height: 6px; margin-right: 0.4em;
  border-radius: 50%; background: var(--gold);
  box-shadow: 0 0 0 3px rgba(231, 199, 110, 0.14);
}

.ht-lanes { display: flex; gap: 0.2rem; }
.ht-lanes button {
  appearance: none; cursor: pointer;
  padding: 0.3rem 0.6rem; border-radius: var(--radius-s);
  border: 1px solid transparent; background: transparent; color: var(--dim);
  font-family: var(--mono); font-size: 0.68rem; font-weight: 500; letter-spacing: 0.07em;
  text-transform: uppercase;
  transition: color var(--dur-fast) var(--ease-out),
              background-color var(--dur-fast) var(--ease-out),
              border-color var(--dur-fast) var(--ease-out);
}
.ht-lanes button:hover { color: var(--ink); background: rgba(255, 255, 255, 0.04); }
.ht-lanes button[aria-selected="true"] {
  color: var(--ground); background: var(--gold); border-color: var(--gold-lit); font-weight: 700;
}

.ht-pane { display: block; margin: 0; padding: 0.3rem 0; list-style: none; counter-reset: none; }
.ht-pane[hidden] { display: none; }
.ht-pane li + li { border-top: 1px solid rgba(35, 40, 56, 0.7); }

.ht-pane a {
  display: grid; align-items: center;
  grid-template-columns: 1.1rem 26px minmax(0, 1fr) minmax(38px, 84px) auto auto;
  gap: 0.6rem;
  padding: 0.52rem clamp(0.8rem, 2vw, 1.15rem);
  text-decoration: none; color: inherit;
  transition: background-color var(--dur-fast) var(--ease-out);
}
.ht-pane a:hover { background: rgba(231, 199, 110, 0.06); }
.ht-pane a:hover .ht-naam { color: var(--gold-lit); }
.ht-pane a:focus-visible { outline: 2px solid var(--gold); outline-offset: -2px; border-radius: 4px; }

.ht-rang { font-family: var(--mono); font-size: 0.7rem; color: var(--dim); text-align: right; }
.ht-pane img {
  width: 26px; height: 26px; display: block; border-radius: 5px;
  border: 1px solid var(--line-lit); background: var(--surface);
}
.ht-naam {
  font-weight: 600; font-size: 0.9rem; color: var(--ink);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  transition: color var(--dur-fast) var(--ease-out);
}
/* Nulpunt is 50%, net als in de grote tabel: anders zijn vijf balken van 55-61%
   vijf even lange streepjes. */
.ht-balk { height: 4px; border-radius: 2px; background: rgba(255, 255, 255, 0.06); overflow: hidden; }
.ht-balk i { display: block; height: 100%; border-radius: inherit; background: var(--gold-dim); }
.ht-wr { font-family: var(--mono); font-size: 0.86rem; font-weight: 700; text-align: right; min-width: 3.6em; }
.ht-wr small { font-size: 0.66em; font-weight: 500; opacity: 0.65; margin-left: 0.1em; }
.ht-wr.wr-hi { color: var(--wr-hi); }
.ht-wr.wr-ok { color: var(--wr-ok); }
.ht-wr.wr-lo { color: var(--wr-lo); }
.ht-wr.wr-bad { color: var(--wr-bad); }
.ht-games {
  font-family: var(--mono); font-size: 0.72rem; color: var(--dim);
  text-align: right; min-width: 4.6em;
}
.ht-games small { display: block; font-size: 0.72em; letter-spacing: 0.08em; opacity: 0.7; }

.ht-voet {
  display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between;
  gap: 0.35rem 1rem;
  padding: 0.65rem clamp(0.8rem, 2vw, 1.15rem);
  border-top: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.012);
  font-size: 0.7rem; color: var(--dim); line-height: 1.45;
}
.ht-voet code { font-family: var(--mono); font-size: 0.94em; color: var(--muted); }
.ht-voet a {
  font-family: var(--mono); font-size: 0.7rem; color: var(--gold);
  text-decoration: none; white-space: nowrap;
  transition: color var(--dur-fast) var(--ease-out);
}
.ht-voet a:hover { color: var(--gold-lit); text-decoration: underline; text-underline-offset: 3px; }

/* Onder ~430px is de balk de eerste die weg mag: de winrate en het aantal
   games moeten blijven staan, de balk is de illustratie ervan. */
@media (max-width: 430px) {
  .ht-pane a { grid-template-columns: 1.1rem 24px minmax(0, 1fr) auto auto; gap: 0.5rem; }
  .ht-balk { display: none; }
}

/* ── Proof strip onder de knoppen (.held-bewijs) ───────────────────────────── */
.held-bewijs {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem 1.4rem;
  margin: 1.6rem 0 0; padding-top: 1.2rem;
  border-top: 1px solid var(--line);
  max-width: 30rem;
}
.held-bewijs b {
  display: block; font-family: var(--mono); font-size: clamp(1.1rem, 1.6vw, 1.35rem);
  font-weight: 700; color: var(--gold); line-height: 1.15;
  font-variant-numeric: tabular-nums;
}
.held-bewijs > div > span {
  display: block; margin-top: 0.15rem;
  font-family: var(--mono); font-size: 0.6rem; letter-spacing: 0.11em;
  text-transform: uppercase; color: var(--dim); line-height: 1.35;
}
.held-bewijs .hb-noot {
  grid-column: 1 / -1; margin: 0.55rem 0 0;
  font-size: 0.76rem; line-height: 1.55; color: var(--dim); max-width: 46ch;
}
@media (max-width: 460px) {
  .held-bewijs { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* ── Screenshot in zijn nieuwe huis (#app) ─────────────────────────────────── */
.app-beeld { max-width: 980px; margin: 0 auto 0.6rem; }
.app-beeld-noot {
  max-width: 980px; margin: 0 auto 2.2rem;
  font-size: 0.76rem; color: var(--dim); text-align: center;
}

@media (prefers-reduced-motion: reduce) {
  .ht-lanes button, .ht-pane a, .ht-naam, .ht-voet a { transition: none; }
}

/* ══════════════════════════════════════════════════════════════════════════
   Home hero, rebuilt: the product and the numbers, not the weather.

   The old hero was a battlefield with a headline on it. This one has to do
   three jobs on one screen -- say what the software does, show the software
   doing it, and put real rows out of the 125,096 recorded games in front of
   somebody who has not scrolled yet.

   Layout: a two-column deck (pitch | product) with a full-width data rail
   under it. Appended last, so these win over the earlier .lol-held block on
   equal specificity.
   ═══════════════════════════════════════════════════════════════════════════ */

.lol-held {
  display: block;
  min-height: 0;
  padding-block: clamp(2.2rem, 4.2vw, 3.4rem) clamp(2rem, 4vw, 3.2rem);
}
/* The wrap was the two-column grid; the deck inside it is now, because the
   rail has to run the full width underneath both columns. */
.lol-held .wrap { display: block; grid-template-columns: none; gap: 0; }

/* The battlefield stays, as ground. It is dimmed twice: the image blends back
   toward --ground, and a flat layer sits over it under the existing
   directional scrim. Without the z-index the ::before would paint *under* the
   image -- an absolute pseudo and an absolute child of the same box stack in
   DOM order, and ::before comes first. */
.lol-held .held-foto { opacity: 0.5; object-position: 74% 56%; }
.lol-held-dek::before {
  content: ""; position: absolute; inset: 0; z-index: 1;
  background: linear-gradient(180deg, rgba(7, 8, 16, 0.60), rgba(7, 8, 16, 0.32) 34%, rgba(7, 8, 16, 0.86));
}
.lol-held-dek::after { z-index: 2; }

.held-deck {
  position: relative;
  display: grid;
  align-items: center;
  grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr);
  gap: clamp(1.6rem, 3.6vw, 3.4rem);
}
@media (max-width: 1000px) { .held-deck { grid-template-columns: 1fr; } }

/* Tighter than before: the first screen now carries a screenshot and a table
   as well, so the headline cannot take half of it. */
.lol-held h1 { font-size: clamp(2.05rem, 1.5rem + 2.6vw, 3.35rem); line-height: 1.04; margin: 0 0 1rem; }
.lol-held .lede { font-size: clamp(0.97rem, 0.93rem + 0.25vw, 1.06rem); max-width: 46ch; margin: 0 0 1.45rem; }
.lol-held .cta-note { margin-top: 0.85rem; }
.lol-held .cta-note a { color: var(--muted); text-underline-offset: 2px; }
.lol-held .cta-note a:hover { color: var(--gold); }

/* ── The three figures that back the headline's number ───────────────────── */
.held-cijfers {
  display: flex; flex-wrap: wrap; gap: clamp(1.1rem, 2.6vw, 2.2rem);
  margin: 1.5rem 0 0; padding-top: 1.15rem; border-top: 1px solid var(--line);
}
.held-cijfers > div { display: flex; flex-direction: column; gap: 0.22rem; }
.held-cijfers dt {
  font-size: clamp(1.15rem, 1rem + 0.55vw, 1.5rem); font-weight: 700;
  color: var(--ink); line-height: 1; letter-spacing: -0.02em;
}
.held-cijfers dd {
  margin: 0; font-size: 0.7rem; color: var(--dim);
  text-transform: uppercase; letter-spacing: 0.1em;
}
.hc-van { color: var(--dim); font-weight: 400; }
.held-bron { font-family: var(--mono); font-size: 0.71rem; line-height: 1.6; color: var(--dim); margin: 0.85rem 0 0; }

/* ── The product, framed and captioned ───────────────────────────────────── */
.held-toon { margin: 0; }
.held-toon .lol-held-beeld { min-height: 0; }
.held-toon figcaption {
  margin-top: 0.72rem; font-size: 0.75rem; line-height: 1.5;
  color: var(--dim); max-width: 46ch;
}

/* ── The data rail: top five per lane, straight out of the dataset ───────── */
.held-rail {
  position: relative;
  margin-top: clamp(1.7rem, 3.4vw, 2.6rem);
  border: 1px solid var(--line-lit); border-radius: 14px; overflow: hidden;
  background: linear-gradient(180deg, rgba(17, 20, 31, 0.92), rgba(7, 8, 16, 0.94));
  box-shadow: var(--lift-2), inset 0 1px 0 rgba(244, 224, 166, 0.08);
}
/* Only where it is real: a blurred pane over the battlefield reads as glass,
   an unsupported one reads as a grey box, so the opaque fill stays the base. */
@supports (backdrop-filter: blur(8px)) {
  .held-rail {
    background: linear-gradient(180deg, rgba(17, 20, 31, 0.78), rgba(7, 8, 16, 0.84));
    backdrop-filter: blur(9px) saturate(120%);
  }
}

/* The radios drive everything. Off-screen but still focusable, so the strip
   keeps arrow-key switching with JavaScript off. */
.hl-radio {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0;
  border: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap;
}

.hl-kop {
  display: flex; flex-wrap: wrap; align-items: center; gap: 0.55rem 1rem;
  padding: 0.8rem 1rem; border-bottom: 1px solid var(--line);
}
.hl-titel {
  margin: 0; font-family: var(--display); font-weight: 700;
  font-size: 0.95rem; letter-spacing: -0.01em; color: var(--ink);
}
.hl-titel em { font-style: normal; color: var(--gold); }
.hl-tabs { display: flex; flex-wrap: wrap; gap: 0.28rem; margin-left: auto; }
.hl-tabs label {
  padding: 0.32rem 0.7rem; border-radius: 999px; border: 1px solid transparent;
  font-size: 0.78rem; color: var(--muted); cursor: pointer;
  transition: color var(--dur-mid) var(--ease-out), background-color var(--dur-mid) var(--ease-out),
    border-color var(--dur-mid) var(--ease-out);
}
.hl-tabs label:hover { color: var(--ink); background: rgba(255, 255, 255, 0.05); }
.hl-meer { font-size: 0.78rem; color: var(--gold); text-decoration: none; white-space: nowrap; }
.hl-meer:hover { color: var(--gold-lit); }

#hl-TOP:checked ~ .hl-kop label[for="hl-TOP"],
#hl-JUNGLE:checked ~ .hl-kop label[for="hl-JUNGLE"],
#hl-MIDDLE:checked ~ .hl-kop label[for="hl-MIDDLE"],
#hl-BOTTOM:checked ~ .hl-kop label[for="hl-BOTTOM"],
#hl-SUPPORT:checked ~ .hl-kop label[for="hl-SUPPORT"] {
  background: var(--gold); border-color: var(--gold); color: #1a1405;
}
#hl-TOP:focus-visible ~ .hl-kop label[for="hl-TOP"],
#hl-JUNGLE:focus-visible ~ .hl-kop label[for="hl-JUNGLE"],
#hl-MIDDLE:focus-visible ~ .hl-kop label[for="hl-MIDDLE"],
