#hl-SUPPORT:focus-visible ~ .hl-kop label[for="hl-SUPPORT"] {
  outline: 2px solid var(--gold); outline-offset: 2px;
}

.hl-pane { display: none; }
#hl-TOP:checked ~ .hl-panes #hlp-TOP,
#hl-JUNGLE:checked ~ .hl-panes #hlp-JUNGLE,
#hl-MIDDLE:checked ~ .hl-panes #hlp-MIDDLE,
#hl-BOTTOM:checked ~ .hl-panes #hlp-BOTTOM,
#hl-SUPPORT:checked ~ .hl-panes #hlp-SUPPORT { display: block; }

.hl-pane ol {
  list-style: none; margin: 0; padding: 0.75rem 0.75rem 0.45rem;
  display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0.55rem;
}
@media (max-width: 1000px) { .hl-pane ol { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@media (max-width: 620px)  { .hl-pane ol { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 400px)  { .hl-pane ol { grid-template-columns: 1fr; } }

.hl-kaart a {
  display: grid; grid-template-columns: auto minmax(0, 1fr);
  column-gap: 0.6rem; row-gap: 0.12rem; align-items: center;
  padding: 0.6rem 0.68rem; border-radius: 10px; text-decoration: none;
  border: 1px solid var(--line); background: rgba(255, 255, 255, 0.02);
  transition: transform var(--dur-mid) var(--ease-out), border-color var(--dur-mid) var(--ease-out),
    background-color var(--dur-mid) var(--ease-out), box-shadow var(--dur-mid) var(--ease-out);
}
.hl-kaart a:hover,
.hl-kaart a:focus-visible {
  transform: translateY(-2px); border-color: var(--line-lit);
  background: rgba(231, 199, 110, 0.05); box-shadow: var(--lift-1);
}
.hl-kaart img {
  grid-row: 1 / span 2; width: 40px; height: 40px;
  border-radius: 8px; border: 1px solid var(--line-lit);
}
.hl-naam {
  display: block; min-width: 0; font-size: 0.85rem; font-weight: 600; color: var(--ink);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.hl-rang { margin-right: 0.4rem; font-size: 0.68rem; color: var(--dim); }
.hl-cijfer { display: flex; align-items: baseline; gap: 0.4rem; min-width: 0; }
.hl-wr { font-size: 0.95rem; font-weight: 700; letter-spacing: -0.02em; }
.hl-wr small { font-size: 0.62em; opacity: 0.75; margin-left: 0.05em; }
.hl-games { font-size: 0.67rem; color: var(--dim); white-space: nowrap; }
.hl-voet {
  margin: 0; padding: 0 0.9rem 0.85rem;
