/* ═══════════════════════════════════════════════════════════════════════════
   PASTE TARGET: site/build.mjs

   1. Insert the three functions below immediately BEFORE the line

          function leaguePagina() {

      (currently line 1037). Everything they touch -- builds, champions, T, CH,
      LANES, catalogus, esc, n, pct, DATE, bar, wrClass, iconOf, itemIcon,
      itemName, tierFor, slugVan -- is already module scope and already defined
      above that point.

   2. In leaguePagina(), REPLACE the call site

          ${modusBalk()}

      (the single line between the hero's closing </section> and
      <section class="band" id="app">) with

          ${metaTabel()}

      Do not delete modusBalk() itself -- classic.html still calls it.
   ═══════════════════════════════════════════════════════════════════════════ */

/**
 * De meest gespeelde kernbuild van een champion in een lane.
 *
 * `core` staat in builds.json al gesorteerd, maar dat is een aanname over een
 * bestand dat een andere generator schrijft -- dus sorteren we hier zelf. Meest
 * GESPEELD, niet best scorend: de tierlijst laat zien wat mensen kochten, niet
 * welke drie items toevallig het hoogste percentage haalden over dertig games.
 */
function kernBuild(baseId, lane) {
  const l = builds.champions?.[String(baseId)]?.lanes?.find((x) => x.lane === lane);
  if (!l) return null;
  const kern = [...(l.core ?? [])].sort((a, b) => b.games - a.games)[0];
  if (!kern?.items?.length) return null;
  return { items: kern.items, games: kern.games, winrate: kern.winrate, boot: (l.boots ?? [])[0] ?? null };
}

/** De buildkolom: laarzen plus drie kernitems, met de steekproef eronder. */
function kernCel(k) {
  if (!k) return `<td class="m-build"><span class="m-build-leeg">&mdash;</span></td>`;
  const rij = [];
  if (k.boot) rij.push([k.boot.baseId, k.boot.naam]);
  for (const id of k.items) rij.push([id, itemName(id)]);
  const tip = `${rij.map(([, naam]) => naam).join(" > ")} — ${n(k.games)} games, ${pct(k.winrate)}% won`;
  return `<td class="m-build">
            <span class="m-build-rij" title="${esc(tip)}">
              ${rij
                .map(
                  ([id, naam]) =>
                    `<img src="${itemIcon(id)}" alt="${esc(naam)}" width="64" height="64" loading="lazy" />`,
                )
                .join("")}
            </span>
            <span class="m-build-n mono">${n(k.games)}<span class="m-eenheid">g</span> &middot; <b class="${wrClass(k.winrate)}">${pct(k.winrate)}<span class="m-eenheid">%</span></b></span>
          </td>`;
}

/**
 * De levende tierlijst op de voorpagina.
 *
 * Dit is het enige blok op de voorpagina dat de dataset zelf laat zien. Iemand
 * die niet weet wat AllMid is, moet hier binnen twee seconden zien dat er echt
 * geteld is: tien namen, een winrate, de ruwe winrate ernaast zodat je ziet wat
 * het gladstrijken deed, het aantal games, en de items die die mensen kochten.
 *
 * Alle vijf de lanes staan in de HTML. Zonder JavaScript staan ze onder elkaar
 * met een kop erboven -- pas als het script draait worden het tabbladen. Nooit
 * andersom: een tabblad dat niet opengaat is inhoud die verdwenen is.
 */
function metaTabel() {
  const cijfers = [
    { v: n(T.games), l: "Games recorded" },
    { v: n(T.playerRows), l: "Player slots parsed" },
    { v: n(T.players), l: "Players seen" },
    { v: `63<span class="m-van"> of 63</span>`, l: "Champions covered" },
    { v: T.patches.map((p) => esc(p)).join(`<span class="m-van"> &middot; </span>`), l: "Patches", klein: true },
    { v: DATE(T.laatsteGame), l: "Newest game", klein: true },
  ]
    .map(
      (c) =>
        `<div class="meta-cijfer"><b${c.klein ? ' class="klein"' : ""}>${c.v}</b><span>${esc(c.l)}</span></div>`,
    )
    .join("");

  const rijen = (lane) =>
    tierFor(lane)
      .map(
        (e, i) => `
          <tr>
            <td class="m-rank mono">${i + 1}</td>
            <td class="m-champ">
              <a href="champion/${slugVan(e.naam)}.html">
                <img src="${iconOf(e.baseId)}" alt="" width="128" height="128" loading="lazy" />
                <span>${esc(e.naam)}</span>
              </a>
            </td>
            <td class="m-bar"><span style="width:${bar(e.winrate).toFixed(1)}%"></span></td>
            <td class="m-wr ${wrClass(e.winrate)}">${pct(e.winrate)}<small>%</small></td>
            <td class="m-raw mono">${pct(e.winrateRuw)}</td>
            <td class="m-games mono">${n(e.games)}</td>
            <td class="m-pick mono">${pct(e.pickRate)}<small>%</small></td>
            ${kernCel(kernBuild(e.baseId, lane))}
          </tr>`,
      )
      .join("");

  const tabs = LANES.map(
    ({ key, label }, i) =>
      `<button type="button" role="tab" id="metatab-${key}" aria-controls="meta-${key}" aria-selected="${i === 0}" tabindex="${i === 0 ? 0 : -1}" data-lane="${key}">${esc(label)}</button>`,
  ).join("");

  const panelen = LANES.map(
    ({ key, label }, i) => `
      <div class="meta-pane${i === 0 ? " is-open" : ""}" id="meta-${key}" role="tabpanel" aria-labelledby="metatab-${key}">
        <h3 class="meta-pane-kop">${esc(label)}</h3>
        <div class="table-scroll meta-scroll">
          <table class="meta-table">
            <caption class="vh">Top ten champions in ${esc(label)} by win rate, from ${n(T.games)} recorded Classic games</caption>
            <thead>
              <tr>
                <th scope="col">#</th>
                <th scope="col">Champion</th>
                <th scope="col"><span class="vh">Win rate, drawn</span></th>
                <th scope="col">Win rate</th>
                <th scope="col">Raw</th>
                <th scope="col">Games</th>
                <th scope="col">Pick</th>
                <th scope="col">Most built</th>
              </tr>
            </thead>
            <tbody>${rijen(key)}</tbody>
          </table>
        </div>
        <p class="meta-vn">
          ${CH.laneQualifiers[key]} of 63 champions cleared the 100-game minimum for ${esc(label)}.
        </p>
      </div>`,
  ).join("");

  return `<section class="band meta-band" id="meta">
  <div class="wrap">
    <div class="sectiekop rise">
      <p class="eyebrow">Live tier list &middot; League Classic</p>
      <h2>Here is the data. Nobody else has it.</h2>
      <p class="sectielede">
        Riot&rsquo;s public API does not carry Classic, so this table exists nowhere but here. Not a
        screenshot and not a sample &mdash; it is the whole pooled dataset, computed by the same code
        that runs inside the app.
      </p>
    </div>

    <div class="meta-cijfers rise">${cijfers}</div>

    <div class="rise">
      <div class="meta-tabs" role="tablist" aria-label="Lane">${tabs}</div>
      ${panelen}
    </div>

    <p class="meta-uitleg">
      <strong>Win rate</strong> is smoothed as <code>(wins + 10) / (games + 20)</code>, so a lucky
      40-game run cannot fake a 70%. <strong>Raw</strong> is the unsmoothed number, printed beside it
      so you can see exactly what the smoothing did. <strong>Most built</strong> is the boots and
      three-item core that lane bought most often, with the games behind that build.
    </p>

    <div class="meta-verder">
      <a class="btn btn-ghost btn-sm" href="classic.html#tiers">Full tables, counters and method</a>
      <a class="btn btn-ghost btn-sm" href="champions.html">All ${catalogus.champions.length} champions</a>
    </div>
  </div>

  <script>
  (function () {
    var sec = document.getElementById("meta");
    if (!sec) return;
    var tabs = [].slice.call(sec.querySelectorAll(".meta-tabs button"));
    var panes = [].slice.call(sec.querySelectorAll(".meta-pane"));
    if (!tabs.length || !panes.length) return;
    // Pas hier de tabbladen aanzetten. Tot dit moment staan alle vijf de lanes
    // gewoon onder elkaar, en dat is ook wat je overhoudt als dit script faalt.
    sec.classList.add("meta-js");
    function kies(tab) {
      tabs.forEach(function (t) {
        var aan = t === tab;
        t.setAttribute("aria-selected", String(aan));
        t.tabIndex = aan ? 0 : -1;
      });
      panes.forEach(function (p) { p.classList.toggle("is-open", p.id === "meta-" + tab.dataset.lane); });
    }
    tabs.forEach(function (tab, i) {
      tab.addEventListener("click", function () { kies(tab); });
      tab.addEventListener("keydown", function (e) {
        var d = e.key === "ArrowRight" ? 1 : e.key === "ArrowLeft" ? -1 : 0;
        if (!d) return;
        e.preventDefault();
        var volgende = tabs[(i + d + tabs.length) % tabs.length];
        kies(volgende);
        volgende.focus();
      });
    });
  })();
  </script>
</section>`;
}

