/* PASTE TARGET: the `css` template literal in site/build.mjs (opens line 1892),
   appended at the very end just before its closing backtick -- i.e. after the
   existing prefers-reduced-motion block and before `;`

   ── Voorpagina: de levende tierlijst ───────────────────────────────────────
   Een tabel met acht kolommen. Dat is bewust dicht: dun opgemaakte data leest
   als marketing, dichte data leest als een meetinstrument. Wat de dichtheid
   leesbaar houdt is niet witruimte maar uitlijning -- alles wat een getal is
   staat rechts, in mono, met tabular-nums, zodat de komma's onder elkaar vallen.
   ─────────────────────────────────────────────────────────────────────────── */

.vh {
  position: absolute; width: 1px; height: 1px; margin: -1px;
  padding: 0; border: 0; overflow: hidden; white-space: nowrap;
  clip: rect(0 0 0 0); clip-path: inset(50%);
}

.meta-band .sectiekop { margin-bottom: clamp(1.6rem, 3vw, 2.2rem); }

/* Zes tegels, gescheiden door de rasterlijn zelf: een pixel achtergrond die
   door de gaps schijnt. Geen border per tegel, dus geen dubbele lijnen. */
.meta-cijfers {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: var(--radius-s);
  overflow: hidden;
  margin: 0 0 clamp(1.6rem, 3vw, 2.4rem);
}
.meta-cijfer { background: var(--surface); padding: 0.9rem 1.05rem; }
.meta-cijfer b {
  display: block;
  font-family: var(--mono); font-weight: 700; font-variant-numeric: tabular-nums;
  font-size: clamp(1.05rem, 0.9rem + 0.5vw, 1.4rem);
  line-height: 1.15; color: var(--gold);
}
.meta-cijfer b.klein { font-size: clamp(0.88rem, 0.84rem + 0.22vw, 1.02rem); color: var(--ink); }
.meta-cijfer span {
  display: block; margin-top: 0.32rem;
  font-size: 0.68rem; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dim);
}
.m-van { color: var(--dim); font-weight: 400; }

/* De tabbladen bestaan alleen als het script gedraaid heeft. Staan ze er niet,
   dan staan alle vijf de lanes onder elkaar en is er niets verdwenen. */
.meta-tabs { display: none; flex-wrap: wrap; gap: 0.4rem; margin: 0 0 1.2rem; }
.meta-js .meta-tabs { display: flex; }
.meta-tabs button {
  font: inherit; font-size: 0.86rem; font-weight: 600;
  padding: 0.44rem 0.95rem; border-radius: 999px;
  border: 1px solid var(--line); background: transparent; color: var(--muted); cursor: pointer;
  transition: color var(--dur-fast) var(--ease-io),
              border-color var(--dur-fast) var(--ease-io),
              background-color var(--dur-fast) var(--ease-io);
}
.meta-tabs button:hover { color: var(--ink); border-color: var(--line-lit); }
.meta-tabs button[aria-selected="true"] {
  color: var(--gold); border-color: var(--gold-dim); background: rgba(231, 199, 110, 0.08);
}

.meta-pane + .meta-pane { margin-top: clamp(2rem, 4vw, 3rem); }
.meta-js .meta-pane { display: none; margin-top: 0; }
.meta-js .meta-pane.is-open { display: block; }
.meta-pane-kop { margin: 0 0 0.8rem; font-size: 1.05rem; letter-spacing: 0.01em; }
.meta-js .meta-pane-kop { display: none; }

.meta-scroll { box-shadow: var(--lift-1); }
.meta-table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }
.meta-table th, .meta-table td { padding: 0.55rem 0.8rem; text-align: right; white-space: nowrap; }
.meta-table thead th {
  font-family: var(--mono); font-size: 0.62rem; font-weight: 500;
  letter-spacing: 0.14em; text-transform: uppercase; color: var(--dim);
  border-bottom: 1px solid var(--line-lit);
}
.meta-table tbody tr + tr td { border-top: 1px solid rgba(35, 40, 56, 0.7); }
.meta-table tbody tr { transition: background-color var(--dur-mid) var(--ease-io); }
.meta-table tbody tr:hover { background: rgba(231, 199, 110, 0.04); }

.m-rank { width: 1%; color: var(--dim); }
.m-champ { text-align: left; }
.m-champ a {
  display: flex; align-items: center; gap: 0.6rem;
  color: var(--ink); text-decoration: none; font-weight: 600;
}
.m-champ a span { transition: color var(--dur-fast) var(--ease-io); }
.m-champ a:hover span { color: var(--gold); }
.m-champ img { width: 30px; height: 30px; border-radius: 5px; flex: none; }

/* Nul zit op 50%, net als in de tierpagina: tien balken vanaf nul zijn tien
   even lange streepjes en zeggen niets. */
.m-bar { width: 14%; min-width: 78px; }
.m-bar span { display: block; height: 4px; border-radius: 2px; background: var(--wr-hi); opacity: 0.75; }

.m-wr { font-family: var(--mono); font-weight: 700; font-variant-numeric: tabular-nums; }
.m-raw, .m-games, .m-pick { color: var(--muted); font-size: 0.84rem; font-variant-numeric: tabular-nums; }
.m-wr small, .m-pick small { font-size: 0.68em; opacity: 0.62; margin-left: 1px; }

.m-build { width: 1%; text-align: left; }
.m-build-rij { display: flex; gap: 3px; }
.m-build-rij img {
  width: 26px; height: 26px; flex: none;
  border-radius: 4px; border: 1px solid var(--line); background: var(--raised);
}
.m-build-n { display: block; margin-top: 0.3rem; font-size: 0.68rem; color: var(--dim); letter-spacing: 0.03em; }
.m-build-n b { font-weight: 700; }
.m-build-leeg { color: var(--dim); }
.m-eenheid { opacity: 0.55; }

.meta-vn { margin: 0.85rem 0 0; font-size: 0.8rem; color: var(--dim); }
.meta-uitleg {
  margin: 1.6rem 0 0; max-width: 78ch;
  font-size: 0.83rem; line-height: 1.65; color: var(--dim);
}
.meta-uitleg strong { color: var(--muted); font-weight: 600; }
.meta-uitleg code { font-family: var(--mono); font-size: 0.9em; color: var(--muted); }

.meta-verder { display: flex; flex-wrap: wrap; gap: 0.7rem; margin-top: 1.6rem; }

/* Op smal scherm niets weghalen -- .table-scroll schuift al horizontaal, en een
   kolom verbergen op een tabel breekt de uitlijning met de koprij. Alleen de
   ademruimte krimpt. */
@media (max-width: 640px) {
  .meta-table { font-size: 0.84rem; }
  .meta-table th, .meta-table td { padding: 0.5rem 0.6rem; }
  .m-build-rij img { width: 24px; height: 24px; }
}

@media (prefers-reduced-motion: reduce) {
  .meta-tabs button, .meta-table tbody tr, .m-champ a span { transition: none; }
}

