/* ══════════════════════════════════════════════════════════════════════════
   HOW TO INSTALL THIS INTO site/build.mjs — three edits, all verified by a
   real build run (node build.mjs completes, all three pages tag-balanced).

   EDIT 1 — REPLACE the two existing functions.
     Delete everything from the line

         /** The app page: what it is, until there is a gallery of screenshots to show. */

     down to (but NOT including) the line

         /**
          * The front page: League of Legends, and what AllMid does with it.

     That range is the old appPagina() and overlayPagina(). Paste the entire
     block below in its place. It defines the new appPagina() and
     overlayPagina() plus everything they share with the front page.

   EDIT 2 — REPLACE the download section inside leaguePagina().
     Find, in the front-page template literal, the block that starts

         <section class="band" id="get">

     and ends with the </section> after

         <p class="cta-note">Or <a href="https://github.com/allmidgg/desktop">read the source</a> first.</p>

     Replace that whole <section>…</section> with exactly:

         ${downloadMoment()}

     Leave the ${existsSync(join(HERE, "img/scheiding.png")) ? ...} divider line
     directly above it untouched — the new section keeps id="get", so the
     .band#get gold glow and the .scheiding + .band#get overlap still apply.

   EDIT 3 — append the CSS from the `css` field to the end of the `css`
     template literal (just before the closing backtick above
     writeFileSync(join(HERE, "style.css"), css, "utf8")).

   Nothing else changes. KENMERKEN and kenmerkBlok() stay where they are for
   the front page; app.html no longer uses them.
   ══════════════════════════════════════════════════════════════════════════ */

/* ═══ Het downloadmoment, de app-pagina en de overlay-pagina ═══════════════
 *
 * Waarom dit meer is dan een knop met een zin erboven: wie hier komt heeft nog
 * nooit een .exe van ons gedraaid. De vraag in zijn hoofd is niet "wil ik dit"
 * maar "wat gebeurt er als ik klik". Alles hieronder beantwoordt die vraag met
 * een feit dat hij zelf kan nakijken: waar de installer landt, welke verzoeken
 * de app aan zijn client doet, wat hij nooit doet, en wat er al in de release
 * zit voordat hij zijn eerste game speelt.
 *
 * Geen enkel cijfer op deze pagina's is met de hand ingetikt. Ze komen alle uit
 * champions.json, builds.json en meta.json, zodat een nieuwe momentopname ze
 * meeneemt in plaats van ze stil te laten verouderen.
 * ────────────────────────────────────────────────────────────────────────── */

const DOWNLOAD_URL = "https://github.com/allmidgg/desktop/releases/latest/download/AllMid-Setup.exe";
const BRON_URL = "https://github.com/allmidgg/desktop";
const LCU_BRON_URL = "https://github.com/allmidgg/desktop/tree/main/src/core/lcu";

/**
 * Wat de installer feitelijk doet. Elke regel staat in electron-builder.yml.
 *
 * De backslash staat dubbel omdat dit een JS-string is; er komt
 * %LOCALAPPDATA%\Programs uit. Eén backslash slikt JavaScript op en dan staat
 * er op de site een pad dat niet bestaat -- dat is hier eerder misgegaan.
 */
const INSTALLER = [
  { label: "File", waarde: "AllMid-Setup.exe" },
  { label: "Windows", waarde: "10 and 11, 64-bit" },
  { label: "Installs to", waarde: "%LOCALAPPDATA%\\Programs" },
  { label: "Admin rights", waarde: "Not required" },
  { label: "Your data", waarde: "%APPDATA%, survives uninstall" },
  { label: "Licence", waarde: "MIT, source public" },
];

/** De eerste drie minuten, in de volgorde waarin ze gebeuren. */
const EERSTE_RUN = [
  {
    kop: "Install it",
    tekst:
      "The installer asks where it should go and shows you the folder &mdash; no silent one-click, " +
      "no administrator prompt. It lands in your own user folder, so Windows never has to be " +
      "asked for permission on your behalf.",
  },
  {
    kop: "Start League",
    tekst:
      "Nothing to configure. The client writes a lockfile when it starts and AllMid reads the port " +
      "out of it, the same way every other client tool does. No port to enter, no token to paste, " +
      "no account to make.",
  },
  {
    kop: "Pick a champion",
    tekst:
      "Champion select opens as its own window the moment the timer starts: who is against whom, " +
      "their record on that champion, the matchup win rate, and what wins on your pick. The rest " +
      "fills in from the games you finish.",
  },
];

/**
 * Elk verzoek dat de app aan je eigen client doet.
 *
 * Deze lijst is het bewijsstuk van de hele pagina. "Geen injectie" is een
 * belofte; een uitgeschreven lijst van je complete netwerkoppervlak is iets wat
 * iemand kan controleren -- en dat is precies waarom hij hier staat en niet in
 * een alinea samengevat wordt. Alles komt uit src/core/lcu en src/core/services.
 */
const LCU_LEEST = [
  { pad: "/lol-summoner/v1/current-summoner", doel: "Which account is logged in" },
  { pad: "/lol-summoner/v2/summoners/puuid/…", doel: "Names for the other nine players" },
  { pad: "/lol-gameflow/v1/gameflow-phase", doel: "Lobby, champion select, or in a game" },
  { pad: "/lol-champ-select/v1/session", doel: "The picks already on your own screen" },
  { pad: "/lol-match-history/v1/products/lol/…", doel: "Games that have finished" },
  { pad: "/lol-ranked/v1/ranked-stats/…", doel: "Rank on the Classic ladder" },
  { pad: "/lol-game-data/assets/v1/…", doel: "Champion, item, rune and mastery names and icons" },
  { pad: "/lol-inventory/v2/inventory/…", doel: "Which runes you already own" },
  { pad: "/lol-loadouts/v4/loadouts/scope/account", doel: "Your current pages, so it can back them up first" },
];

/** Het enige dat de app terugschrijft, en alleen als je erom vraagt. */
const LCU_SCHRIJFT = [
  {
    pad: "/lol-loadouts/v4/loadouts/…",
    doel: "Your mastery or rune page &mdash; only when you ask, and never before the backup is written",
  },
];

/**
 * De weigeringen. Stuk voor stuk iets dat een concurrent wél doet of ooit deed,
 * anders is het geen onderscheid maar een opsomming van dingen die niemand doet.
 */
const NOOIT = [
  "Read the game&rsquo;s memory",
  "Inject a DLL or hook the game process",
  "Automate your mouse or your keyboard",
  "Ask for, store or transmit your password",
  "Make you create an account or sign in",
  "Send telemetry, analytics or usage pings",
  "Show what the game hides &mdash; enemy cooldowns, ward positions, ultimate timers",
];

/**
 * Wat er in de release zit voordat je iets speelt.
 *
 * Geteld uit de databestanden zelf, niet overgeschreven. Zodra de crawler
 * verder is en de momentopname ververst wordt, veranderen deze cijfers mee.
 */
function inDeDoos() {
  let matchupRegels = 0;
  let laneTabellen = 0;
  for (const c of Object.values(champions.champions)) {
    for (const l of c.lanes ?? []) {
      if (l.qualified) laneTabellen++;
      matchupRegels += (l.beats?.length ?? 0) + (l.losesTo?.length ?? 0);
    }
  }

  let buildRegels = 0;
  for (const c of Object.values(builds.champions)) {
    for (const l of c.lanes ?? []) {
      buildRegels +=
        (l.items?.length ?? 0) +
        (l.boots?.length ?? 0) +
        (l.starters?.length ?? 0) +
        (l.spells?.length ?? 0);
    }
  }

  // Speelduur staat alleen in meta.json en kan er ontbreken; dan tonen we hem niet.
  const seconden = Number(MT.gemiddeldeDuurSeconden) || 0;
  const uren = seconden ? Math.round((T.games * seconden) / 3600) : null;

  return { matchupRegels, laneTabellen, buildRegels, uren };
}

/** De vier cijfers die zeggen hoe groot "het zit er al in" werkelijk is. */
function doosCijfers() {
  const d = inDeDoos();
  const rijen = [
    [n(T.games), "Games recorded"],
    [n(d.buildRegels), "Build rows"],
    [n(d.matchupRegels), "Lane matchups"],
    [n(d.laneTabellen), "Champion &times; lane tables"],
  ];
  return `<div class="doos-cijfers">
    ${rijen.map(([w, l]) => `<div class="doos-cijfer"><b>${w}</b><span>${l}</span></div>`).join("")}
  </div>`;
}

/**
 * De regel die van "125.096" een gevoel maakt.
 *
 * Een getal met zes cijfers leest als een claim. Dezelfde hoeveelheid in uren
 * is dezelfde meting, alleen in een eenheid waar een mens iets bij voelt. Beide
 * velden komen uit meta.json; ontbreekt de speelduur, dan vervalt de zin.
 */
function doosZin() {
  const d = inDeDoos();
  const periode =
    T.eersteGame && T.laatsteGame
      ? ` recorded between ${DATE(T.eersteGame)} and ${DATE(T.laatsteGame)}`
      : "";
  const uren = d.uren ? `, together <strong>${n(d.uren)} hours</strong> of Classic` : "";
  return `${n(T.games)} games${uren}${periode}, on patches ${T.patches.join(" and ")}.`;
}

/** De drie stappen, gedeeld door de voorpagina en de app-pagina. */
function eersteRunStappen() {
  return `<ol class="stappen">
    ${EERSTE_RUN.map(
      (s, i) => `<li class="stap">
      <span class="stap-nr">${i + 1}</span>
      <div class="stap-tekst">
        <h3>${esc(s.kop)}</h3>
        <p>${s.tekst}</p>
      </div>
    </li>`,
    ).join("")}
  </ol>`;
}

/**
 * De bewijstabel: leest, schrijft, nooit.
 *
 * Drie kolommen naast elkaar en niet drie alinea's onder elkaar, omdat de vorm
 * hier het argument is. Wie dit ziet, ziet in één blik dat de lijst die telt de
 * kortste van de drie is.
 */
function bewijsTabel() {
  const rij = (r, methode) => `<tr>
    <td class="bw-methode"><span class="bw-verb bw-${methode.toLowerCase()}">${methode}</span></td>
    <td class="bw-pad"><code>${esc(r.pad)}</code></td>
    <td class="bw-doel">${r.doel}</td>
  </tr>`;

  return `<div class="bewijs">
    <div class="bewijs-tabelwrap">
      <table class="bewijs-tabel">
        <caption>Every request AllMid makes to your client, in full</caption>
        <thead>
          <tr><th scope="col">Method</th><th scope="col">Local endpoint</th><th scope="col">What for</th></tr>
        </thead>
        <tbody>
          ${LCU_LEEST.map((r) => rij(r, "GET")).join("")}
          ${LCU_SCHRIJFT.map((r) => rij(r, "PATCH")).join("")}
        </tbody>
      </table>
    </div>
    <p class="bewijs-noot">
      All of it over <code>127.0.0.1</code>, to the local HTTPS server your own client runs &mdash;
      the same interface Blitz, Porofessor and OP.GG&rsquo;s desktop app use. That list is the app&rsquo;s
      entire surface toward League, and it lives in
      <a href="${LCU_BRON_URL}"><code>src/core/lcu/</code></a>. The release binaries are built by the
      GitHub Actions workflow in that repository, not on somebody&rsquo;s laptop, so you can build it
      yourself and compare.
    </p>
  </div>`;
}

/** De weigeringen, als lijst. Kort gehouden: elk woord erbij verzwakt hem. */
function nooitLijst() {
  return `<ul class="nooitlijst">
    ${NOOIT.map((x) => `<li>${x}</li>`).join("")}
  </ul>`;
}

/**
 * Het ene ding dat de app wél verstuurt.
 *
 * Dit weglaten zou de veiligheidssectie sterker laten lijken en minder waar
 * maken, en dat is een slechte ruil: iemand die het zelf ontdekt in de
 * instellingen gelooft daarna de rest ook niet meer. De tekst hieronder zegt
 * hetzelfde als de toelichting bij `shareMatches` in src/core/services/settings.ts.
 */
function deelBlok() {
  return `<div class="delen">
    <div class="delen-tekst">
      <p class="delen-label">The one thing it sends</p>
      <h3>Match results, and a switch to stop it</h3>
      <p>
        There is no public dataset for this mode, so the app builds one. What goes over the line is the
        same scoreboard all ten players see afterwards: champions, positions, result, KDA, CS, gold,
        final items, summoner spells. Never credentials, never anything from your client that was not
        already in that game. It asks the server which game IDs it is missing first, so overlapping
        users cost nothing.
      </p>
      <p>
        It is on by default, the first run says so in plain words, and it is one checkbox to turn off.
        Empty the server field instead and nothing leaves your machine at all.
      </p>
    </div>
    <div class="delen-cijfer">
      <b>${n(T.players)}</b>
      <span>Players seen so far</span>
      <p>Every one of them a game somebody chose to share.</p>
    </div>
  </div>`;
}

/**
 * Het downloadmoment op de voorpagina.
 *
 * Vervangt de oude .downloadblok. De sectie houdt `class="band ... " id="get"`
 * aan, zodat de goudgloed die al op .band#get staat blijft werken en de
 * scheidingsafbeelding er nog overheen valt.
 */
function downloadMoment() {
  const feiten = INSTALLER.map(
    (f) => `<div class="if-rij"><dt>${esc(f.label)}</dt><dd>${esc(f.waarde)}</dd></div>`,
  ).join("");

  return `<section class="band aankomst" id="get">
  <div class="wrap">
    <div class="aankomst-kop rise">
      <p class="eyebrow">Download</p>
      <h2>Install it once. It is working before your next game starts.</h2>
      <p class="aankomst-lede">
        Free, open source, and finished on arrival &mdash; the whole Classic dataset ships inside the
        release, so the app is useful the first time you open it rather than after a month of
        collecting.
      </p>
    </div>

    <div class="aankomst-kaart rise">
      <div class="ak-actie">
        <a class="btn btn-primary btn-groot" href="${DOWNLOAD_URL}">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3v12" /><path d="m7 11 5 5 5-5" /><path d="M4 20h16" /></svg>
          Download for Windows
        </a>
        <p class="ak-meta mono">AllMid-Setup.exe &middot; Windows 10 &amp; 11 &middot; 64-bit &middot; MIT</p>
        <p class="ak-tweede">
          <a href="app.html">See what it does</a> &middot; <a href="${BRON_URL}">read the source first</a>
        </p>
        <p class="ak-osnoot" data-nietwindows hidden>
          Heads up: AllMid is Windows-only. It reads the League client running on your own machine, and
          the installer is built for 64-bit Windows.
        </p>
      </div>

      <dl class="ak-feiten">${feiten}</dl>
    </div>

    <p class="ak-waarschuwing rise">
      <strong>Windows SmartScreen may warn you on first run.</strong> Code signing is in progress; until a
      release has enough downloads to build reputation, that warning appears for everyone who publishes
      without a certificate. If it bothers you, <a href="${BRON_URL}">build it from source</a> &mdash; the
      instructions produce the same binary.
    </p>

    ${eersteRunStappen()}

    <div class="doos rise">
      <div class="doos-kop">
        <h3>It already knows the mode</h3>
        <p>${doosZin()} Compiled into the release, so there is nothing to download afterwards and nothing to wait for.</p>
      </div>
      ${doosCijfers()}
    </div>

    <p class="ak-slot rise">
      No account. No telemetry. No injection, no DLL, no memory reading &mdash;
      <a href="app.html#veilig">here is every request it makes to your client</a>, written out in full.
    </p>
  </div>
</section>

<script>
(function () {
  // Windows-only is een feit, geen verwijt. Zichtbaar maken we het alleen voor
  // wie er iets aan heeft; met JS uit blijft de regel gewoon verborgen.
  var noot = document.querySelector("[data-nietwindows]");
  if (!noot) return;
  var opWindows = /Win/i.test(navigator.userAgent || "") ||
    /Windows/i.test((navigator.userAgentData && navigator.userAgentData.platform) || "");
  if (!opWindows) noot.hidden = false;
})();
</script>`;
}

/**
 * De app-pagina.
 *
 * Vijf schermen die bestaan, twee schermafdrukken van het echte ding, en
 * daarna de reden om hem te vertrouwen. De schermafdrukken worden alleen
 * ingevoegd als het bestand er is: een gebroken plaatje is erger dan geen.
 */
function appPagina() {
  const figuur = (pad, alt, bijschrift) =>
    existsSync(join(HERE, pad))
      ? `<figure class="appbeeld">
        <img src="${pad}" alt="${esc(alt)}" loading="lazy" />
        <figcaption>${bijschrift}</figcaption>
      </figure>`
      : "";

  const SCHERMEN = [
    {
      naam: "Live",
      tekst:
        "Where you are right now, and the Classic games you just played &mdash; items, summoner spells, KDA.",
    },
    {
      naam: "Champion select",
      tekst:
        "Its own window, opened by the timer. Per lane: who is against whom, their rank and form, their " +
        "record on that champion, the matchup win rate, and the counters that hold up in that lane.",
    },
    {
      naam: "Meta",
      tekst:
        "Tier lists per lane, and per champion the builds, summoner spells and matchups &mdash; the same " +
        "numbers this site shows, computed by the same code.",
    },
    { naam: "Profile", tekst: "Your own record, plus a search box for any player." },
    {
      naam: "Runes &amp; Masteries",
      tekst:
        "The classic 30-point mastery trees, and rune suggestions built only from runes you actually own. " +
        "Auto Set Best Masteries is a checkbox: leave it on and the page follows whichever champion you " +
        "pick, including when you switch mid-select.",
    },
  ];

  const schermlijst = `<div class="schermen">
    ${SCHERMEN.map(
      (s) => `<div class="scherm">
      <h3 class="scherm-naam">${s.naam}</h3>
      <p>${s.tekst}</p>
    </div>`,
    ).join("")}
  </div>`;

  const held = existsSync(join(HERE, "img/app/allmid-main.png"))
    ? `<div class="app-held rise">
      <img src="img/app/allmid-main.png" alt="The AllMid desktop app" loading="eager" />
    </div>`
    : "";

  return paginaGeraamte({
    hier: "app",
    titel: "The app",
    eyebrow: "The desktop app",
    kop: "AllMid on your machine, reading your own client",
    lede:
      // Letterlijke tekens en geen entiteiten: paginaGeraamte stopt de lede ook in de
      // meta-description, en daar zou &mdash; als &amp;mdash; in de zoekresultaten staan.
      "Riot’s public API does not carry Classic, so the numbers have to come from the client itself. " +
      "AllMid reads the local APIs Riot already ships — no injection, no memory reading, no DLL in " +
      "the game process — and arrives with the whole community dataset already inside it.",
    inhoud: `
      ${held}

      <div class="geraamte-cta rise">
        <a class="btn btn-primary btn-groot" href="${DOWNLOAD_URL}">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3v12" /><path d="m7 11 5 5 5-5" /><path d="M4 20h16" /></svg>
          Download for Windows
        </a>
        <a class="btn btn-ghost" href="${BRON_URL}">Read the source</a>
      </div>
      <p class="ak-meta mono">AllMid-Setup.exe &middot; Windows 10 &amp; 11 &middot; 64-bit &middot; MIT &middot; no account</p>

      <section class="appsectie" id="schermen">
        <div class="sectiekop">
          <p class="eyebrow">Five screens</p>
          <h2>What is actually in it</h2>
        </div>
        ${schermlijst}
        <div class="appbeelden">
          ${figuur(
            "img/champion-select.png",
            "AllMid champion select",
            "Champion select, lane by lane: who is against whom, their rank and form, their record on that champion, the matchup win rate, and what wins on your pick.",
          )}
          ${figuur(
            "img/meta.png",
            "AllMid meta screen",
            "Meta: tier lists per lane, and per champion the builds, spells and matchups &mdash; with the sample size on every row.",
          )}
        </div>
      </section>

      <section class="appsectie" id="veilig">
        <div class="sectiekop">
          <p class="eyebrow">Is this safe to run?</p>
          <h2>Fair question. Here is the whole answer.</h2>
          <p class="sectielede">
            It is a fair thing to ask of any executable that talks to your game client, and the honest
            answer is a list rather than a paragraph. This is every request AllMid makes, and everything
            it refuses to do.
          </p>
        </div>
        ${bewijsTabel()}
        <div class="nooit">
          <h3>What it never does</h3>
          ${nooitLijst()}
          <p class="nooit-noot">
            Not a policy we chose to be nice: Riot&rsquo;s third-party rules forbid exactly the last one, and
            Vanguard blocks injection into League by design. A tool that gets you banned is not a tool.
          </p>
        </div>
        ${deelBlok()}
      </section>

      <section class="appsectie" id="doos">
        <div class="sectiekop">
          <p class="eyebrow">In the release</p>
          <h2>Useful the first time you open it</h2>
          <p class="sectielede">${doosZin()}</p>
        </div>
        ${doosCijfers()}
        <p class="doos-noot">
          Every one of those rows carries the number of games behind it, in the app exactly as on this
          site. A build with nine games behind it says nine, and a lane too thin to rank says so instead
          of showing a percentage.
        </p>
      </section>

      <section class="appsectie" id="beginnen">
        <div class="sectiekop">
          <p class="eyebrow">Getting started</p>
          <h2>Three steps, none of them configuration</h2>
        </div>
        ${eersteRunStappen()}
        <dl class="ak-feiten los">${INSTALLER.map(
          (f) => `<div class="if-rij"><dt>${esc(f.label)}</dt><dd>${esc(f.waarde)}</dd></div>`,
        ).join("")}</dl>
        <div class="bouwzelf">
          <h3>Or build it yourself</h3>
          <p>Node 20 or newer, on Windows. The installers land in <code>dist/</code>.</p>
          <pre class="bouwcode"><code>npm install
npm run build
npm run package</code></pre>
          <p class="bouw-noot">
            Same source, same output. That is the point of publishing it:
            <a href="${BRON_URL}">the whole pipeline is in the repository</a>, so every number the app
            shows can be traced back to the code that counted it.
          </p>
        </div>
      </section>

      <div class="geraamte-cta rise">
        <a class="btn btn-primary btn-groot" href="${DOWNLOAD_URL}">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3v12" /><path d="m7 11 5 5 5-5" /><path d="M4 20h16" /></svg>
          Download for Windows
        </a>
        <a class="btn btn-ghost" href="overlay.html">See the overlay</a>
      </div>`,
  });
}

/**
 * De overlay-pagina.
 *
 * De ja/nee-splitsing blijft, want dat is het hart ervan. Wat erbij komt is het
 * ongemakkelijke deel: hij kan niet over exclusive fullscreen tekenen. Dat
 * verzwijgen levert precies één ding op -- iemand die de app installeert, niets
 * ziet, en concludeert dat hij stuk is.
 */
function overlayPagina() {
  const luik = `<div class="tweeluik">
    <div class="tl-kolom tl-ja">
      <h3>On the panel</h3>
      <ul>
        <li>Objective respawn timers, counted from a kill the whole lobby watched</li>
        <li>The gold difference in items on the field</li>
        <li>Your own skill order, as you level it</li>
        <li>A nudge when your trinket slot is sitting empty</li>
      </ul>
    </div>
    <div class="tl-kolom tl-nee">
      <h3>Never on it</h3>
      <ul>
        <li>Enemy ability cooldowns</li>
        <li>Ultimate timers on portraits</li>
        <li>Ward positions</li>
        <li>Anything the game did not already show both teams</li>
      </ul>
      <p class="tl-waarom">
        Not because we could not build it &mdash; because Riot&rsquo;s third-party rules forbid
        exactly this, and a tool that gets you banned is not a tool.
      </p>
    </div>
  </div>`;

  /**
   * De hersteltijden staan hier omdat ze aanname zijn, niet meting: Season
   * 3-waarden tot iemand een Classic-game met een stopwatch naast zich uitzit.
   * Ze staan in src/core/services/liveInzichten.ts als HERSTELTIJD, en dit
   * blokje zegt er zelf bij dat ze onzeker zijn.
   */
  const timers = `<div class="timertabel">
    <h3>What it counts forward from</h3>
    <table>
      <thead><tr><th scope="col">Objective</th><th scope="col">Back after</th></tr></thead>
      <tbody>
        <tr><td>Dragon</td><td class="mono">6:00</td></tr>
        <tr><td>Baron</td><td class="mono">7:00</td></tr>
        <tr><td>Inhibitor</td><td class="mono">5:00</td></tr>
      </tbody>
    </table>
    <p class="timer-noot">
      Season 3 values, and an assumption until somebody times a Classic game properly. They sit in the
      source as named constants for exactly that reason, so correcting them is one line rather than a
      hunt. If you have measured them, <a href="${BRON_URL}/issues">tell us and we will fix it</a>.
    </p>
  </div>`;

  const gedrag = `<ul class="gedraglijst">
    <li><b>Off by default.</b> An overlay that appears over your game uncalled for is something you switch on, not something you discover mid-fight.</li>
    <li><b>Click-through.</b> Frameless and transparent, and it never swallows a click meant for the game. Unlock it to drag it somewhere else; it remembers where you left it.</li>
    <li><b>Only while a Classic game runs.</b> It appears when one starts and disappears when it ends. There is nothing to close.</li>
    <li><b>Stays on top.</b> Being topmost is a flag, not a rank &mdash; a game taking the foreground restacks that band. AllMid re-asserts it on the poll it already runs, so the panel does not quietly slide behind the game.</li>
  </ul>`;

  const fullscreen = `<div class="eerlijk">
    <h3>It cannot draw over exclusive fullscreen</h3>
    <p>
      Neither can Discord, and neither can anything else that does not inject code into the game process.
      Overwolf&rsquo;s platform reaches it because it does exactly that; Vanguard blocks injection into League
      by design and Riot has said the blocking is intended. We are not going to do it.
    </p>
    <p>
      So League has to run <strong>Borderless</strong> &mdash; or Fullscreen, which Windows quietly composites
      for DX11 games anyway. Rather than show you an empty screen and let you conclude the app is broken,
      AllMid reads League&rsquo;s own <code>game.cfg</code>, notices the setting, and says so.
    </p>
  </div>`;

  return paginaGeraamte({
    hier: "overlay",
    titel: "The overlay",
    eyebrow: "The in-game overlay",
    kop: "On top of the game, and only what the game already shows",
    lede:
      "A small panel over a running game. It carries arithmetic on things both teams can already see " +
      "— a dragon whose death put a banner on all ten screens, gold the scoreboard shows — " +
      "and deliberately nothing else.",
    inhoud: `${luik}

      <section class="appsectie">
        <div class="sectiekop">
          <p class="eyebrow">How it behaves</p>
          <h2>Four things worth knowing before you switch it on</h2>
        </div>
        ${gedrag}
      </section>

      <section class="appsectie">
        <div class="tweekolom">
          ${timers}
          <div class="eerlijk">
            <h3>Item gold, not a gold lead</h3>
            <p>
              The running game reports gold for the player at the keyboard and for nobody else, so a real
              gold lead is not available to any overlay. What is left is the value of everything ten players
              are carrying, which is presumably why Blitz ships an &ldquo;item value difference&rdquo; too.
            </p>
            <p>
              It is not the same number and the panel does not pretend it is: gold in the pocket and gold
              already spent both count towards a lead, and only the spent half shows up here.
            </p>
          </div>
        </div>
      </section>

      <section class="appsectie">
        ${fullscreen}
      </section>

      <div class="geraamte-cta rise">
        <a class="btn btn-primary btn-groot" href="${DOWNLOAD_URL}">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3v12" /><path d="m7 11 5 5 5-5" /><path d="M4 20h16" /></svg>
          Download for Windows
        </a>
        <a class="btn btn-ghost" href="app.html#veilig">What it never does</a>
      </div>`,
  });
}

css:
/* ── Het downloadmoment, de app-pagina en de overlay-pagina ───────────────────
   Alles hieronder hangt aan bestaande tokens; er komt geen nieuwe kleur bij. De
   sectie houdt id="get", zodat de goudgloed op .band#get en de overlap met de
   scheidingsafbeelding blijven werken.

   Geen backslashes in dit blok: de stylesheet is een JS-template-literal en een
   losse backslash wordt daar opgegeten voordat de browser hem ziet.
   ─────────────────────────────────────────────────────────────────────────── */

.aankomst { text-align: left; }
.aankomst-kop { max-width: 46ch; margin: 0 0 2.4rem; }
.aankomst-kop h2 {
  margin: 0.35rem 0 0.8rem;
  font-size: clamp(2rem, 1.4rem + 2.6vw, 3.15rem);
  letter-spacing: -0.033em;
}
.aankomst-lede { margin: 0; color: var(--muted); font-size: 1.02rem; max-width: 52ch; }

/* De kaart: knop links, harde feiten rechts. Twee kolommen omdat de feiten geen
   voetnoot zijn maar het antwoord op "wat gebeurt er als ik klik". */
.aankomst-kaart {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 0.95fr);
  gap: clamp(1.4rem, 3vw, 2.8rem);
  align-items: center;
  padding: clamp(1.4rem, 3vw, 2.2rem);
  border: 1px solid var(--line-lit);
  border-radius: var(--radius);
  background:
    radial-gradient(120% 150% at 0% 0%, rgba(231, 199, 110, 0.075), transparent 62%),
    var(--surface);
  box-shadow: var(--shadow);
}
@media (max-width: 880px) { .aankomst-kaart { grid-template-columns: 1fr; align-items: start; } }

.ak-actie { display: grid; justify-items: start; gap: 0.7rem; }

.btn-groot {
  padding: 1rem 2.1rem;
  font-size: 1.02rem;
  border-radius: 7px;
  box-shadow: 0 14px 38px -12px rgba(231, 199, 110, 0.52);
  transition: transform var(--dur-fast) var(--ease-out),
              background var(--dur-fast) var(--ease-io),
              box-shadow var(--dur-mid) var(--ease-out);
}
.btn-groot:hover { box-shadow: 0 20px 48px -12px rgba(231, 199, 110, 0.66); }
.btn-groot svg { width: 19px; height: 19px; }

.ak-meta {
  margin: 0;
  font-size: 0.7rem;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--dim);
}
.ak-tweede { margin: 0; font-size: 0.9rem; color: var(--muted); }
.ak-tweede a {
  color: var(--muted);
  text-decoration: none;
  border-bottom: 1px solid var(--line-lit);
  transition: color var(--dur-fast) var(--ease-io), border-color var(--dur-fast) var(--ease-io);
}
.ak-tweede a:hover { color: var(--gold); border-bottom-color: var(--gold-dim); }

/* Alleen zichtbaar voor wie niet op Windows zit; JS zet hidden eraf. */
.ak-osnoot {
  margin: 0.2rem 0 0;
  font-size: 0.86rem;
  color: var(--wr-lo);
  max-width: 46ch;
}

/* De feitenlijst. Tabulaire waardes zodat de paden onder elkaar uitlijnen. */
.ak-feiten { margin: 0; display: grid; gap: 1px; background: var(--line); border: 1px solid var(--line); border-radius: var(--radius-s); overflow: hidden; }
.ak-feiten.los { margin-top: 1.6rem; max-width: 640px; }
.if-rij {
  display: grid;
  grid-template-columns: minmax(0, 8.5rem) minmax(0, 1fr);
  gap: 0.9rem;
  align-items: baseline;
  padding: 0.62rem 0.95rem;
  background: var(--raised);
}
.if-rij dt {
  font-family: var(--mono);
  font-size: 0.62rem;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--dim);
}
.if-rij dd { margin: 0; font-family: var(--mono); font-size: 0.83rem; color: var(--ink); overflow-wrap: anywhere; }

.ak-waarschuwing {
  margin: 1.4rem 0 0;
  padding: 0.9rem 1.1rem;
  border: 1px solid var(--line);
  border-left: 2px solid var(--wr-lo);
  border-radius: var(--radius-s);
  background: rgba(255, 180, 84, 0.045);
  font-size: 0.88rem;
  color: var(--muted);
  max-width: 74ch;
}
.ak-waarschuwing strong { color: var(--ink); font-weight: 600; }
.ak-waarschuwing a { color: var(--gold); text-decoration: none; border-bottom: 1px solid var(--gold-dim); }

.ak-slot {
  margin: 2.4rem 0 0;
  font-size: 0.95rem;
  color: var(--muted);
  max-width: 70ch;
}
.ak-slot a { color: var(--gold); text-decoration: none; border-bottom: 1px solid var(--gold-dim); }
.ak-slot a:hover { color: var(--gold-lit); }

/* ── De drie stappen ─────────────────────────────────────────────────────── */
.stappen {
  list-style: none;
  margin: clamp(2rem, 4vw, 3rem) 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: var(--radius-s);
  overflow: hidden;
}
@media (max-width: 800px) { .stappen { grid-template-columns: 1fr; } }
.stap {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.9rem;
  padding: 1.15rem 1.25rem;
  background: var(--raised);
}
.stap-nr {
  font-family: var(--mono);
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--gold);
  width: 1.7rem; height: 1.7rem;
  display: grid; place-items: center;
  border: 1px solid var(--gold-dim);
  border-radius: 50%;
  align-self: start;
}
.stap-tekst h3 { margin: 0.1rem 0 0.45rem; font-size: 1.02rem; }
.stap-tekst p { margin: 0; font-size: 0.88rem; color: var(--muted); line-height: 1.62; }

/* ── Wat er in de release zit ────────────────────────────────────────────── */
.doos {
  margin-top: clamp(2rem, 4vw, 3rem);
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr);
  gap: clamp(1.3rem, 3vw, 2.6rem);
  align-items: center;
}
@media (max-width: 900px) { .doos { grid-template-columns: 1fr; } }
.doos-kop h3 { margin: 0 0 0.7rem; font-size: clamp(1.25rem, 2.2vw, 1.6rem); }
.doos-kop p { margin: 0; color: var(--muted); font-size: 0.93rem; max-width: 54ch; }
.doos-kop strong { color: var(--gold); font-weight: 600; font-family: var(--mono); }

.doos-cijfers { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1px; background: var(--line); border: 1px solid var(--line); border-radius: var(--radius-s); overflow: hidden; }
@media (max-width: 460px) { .doos-cijfers { grid-template-columns: 1fr; } }
.doos-cijfer { padding: 1rem 1.1rem; background: var(--raised); display: grid; gap: 0.3rem; }
.doos-cijfer b {
  font-family: var(--mono); font-size: 1.45rem; font-weight: 700;
  color: var(--gold); letter-spacing: -0.01em; font-variant-numeric: tabular-nums;
}
.doos-cijfer span {
  font-family: var(--mono); font-size: 0.6rem; letter-spacing: 0.13em;
  text-transform: uppercase; color: var(--dim);
}
.doos-noot { margin: 1.4rem 0 0; font-size: 0.89rem; color: var(--muted); max-width: 68ch; }

/* ── De app-pagina ───────────────────────────────────────────────────────── */
.app-held {
  margin: 0 0 2rem;
  border: 1px solid var(--line-lit);
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface);
  box-shadow: var(--shadow);
}
.app-held img { width: 100%; height: auto; display: block; }

.appsectie { margin-top: clamp(3rem, 6vw, 5rem); padding-top: clamp(2rem, 4vw, 3rem); border-top: 1px solid var(--line); }
.appsectie .sectiekop { margin-bottom: 1.8rem; }
.appsectie .sectiekop h2 { font-size: clamp(1.5rem, 2.6vw, 2.1rem); }
.appsectie .sectielede { margin: 0.8rem 0 0; color: var(--muted); font-size: 0.95rem; max-width: 66ch; }

.schermen { display: grid; grid-template-columns: repeat(auto-fit, minmax(255px, 1fr)); gap: 1px; background: var(--line); border: 1px solid var(--line); border-radius: var(--radius-s); overflow: hidden; }
.scherm { padding: 1.15rem 1.25rem; background: var(--raised); }
.scherm-naam {
  margin: 0 0 0.5rem;
  font-family: var(--mono); font-size: 0.66rem; font-weight: 700;
  letter-spacing: 0.14em; text-transform: uppercase; color: var(--gold);
  font-stretch: normal;
}
.scherm p { margin: 0; font-size: 0.88rem; color: var(--muted); line-height: 1.62; }

.appbeelden { display: grid; gap: clamp(1.2rem, 2.5vw, 2rem); margin-top: clamp(1.4rem, 3vw, 2.2rem); }
.appbeeld { margin: 0; }
.appbeeld img {
  width: 100%; height: auto; display: block;
  border: 1px solid var(--line-lit); border-radius: var(--radius-s);
  box-shadow: 0 24px 54px -30px rgba(0, 0, 0, 0.9);
}
.appbeeld figcaption { margin-top: 0.7rem; font-size: 0.84rem; color: var(--dim); max-width: 74ch; }

/* ── De bewijstabel ──────────────────────────────────────────────────────── */
.bewijs { margin: 0; }
.bewijs-tabelwrap { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius-s); }
.bewijs-tabel { width: 100%; min-width: 620px; border-collapse: collapse; }
.bewijs-tabel caption {
  text-align: left; padding: 0.85rem 1.1rem 0.75rem;
  font-family: var(--mono); font-size: 0.63rem; letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--dim);
  border-bottom: 1px solid var(--line);
}
.bewijs-tabel th {
  text-align: left; padding: 0.6rem 1.1rem;
  font-family: var(--mono); font-size: 0.58rem; font-weight: 500;
  letter-spacing: 0.14em; text-transform: uppercase; color: var(--dim);
  border-bottom: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.012);
}
.bewijs-tabel td { padding: 0.62rem 1.1rem; border-bottom: 1px solid var(--line); vertical-align: baseline; }
.bewijs-tabel tbody tr:last-child td { border-bottom: 0; }
.bewijs-tabel tbody tr:hover td { background: rgba(255, 255, 255, 0.018); }

.bw-methode { width: 1%; white-space: nowrap; }
.bw-verb {
  display: inline-block;
  font-family: var(--mono); font-size: 0.6rem; font-weight: 700;
  letter-spacing: 0.1em;
  padding: 0.2rem 0.44rem; border-radius: 4px; border: 1px solid var(--line-lit);
  color: var(--muted);
}
.bw-get { border-color: var(--line-lit); color: var(--muted); }
.bw-patch { border-color: var(--gold-dim); color: var(--gold); background: rgba(231, 199, 110, 0.07); }
.bw-pad code { font-family: var(--mono); font-size: 0.8rem; color: var(--ink); overflow-wrap: anywhere; }
.bw-doel { font-size: 0.87rem; color: var(--muted); }

.bewijs-noot { margin: 1rem 0 0; font-size: 0.87rem; color: var(--muted); max-width: 76ch; }
.bewijs-noot code { font-family: var(--mono); font-size: 0.82rem; color: var(--ink); }
.bewijs-noot a { color: var(--gold); text-decoration: none; border-bottom: 1px solid var(--gold-dim); }

/* ── De weigeringen ──────────────────────────────────────────────────────── */
.nooit {
  margin-top: clamp(1.6rem, 3vw, 2.4rem);
  padding: 1.4rem 1.5rem;
  border: 1px solid var(--line);
  border-radius: var(--radius-s);
  background: rgba(255, 255, 255, 0.014);
}
.nooit h3 { margin: 0 0 1rem; font-size: 1.05rem; }
.nooitlijst {
  list-style: none; margin: 0; padding: 0;
  display: grid; grid-template-columns: repeat(auto-fit, minmax(270px, 1fr)); gap: 0.55rem 1.6rem;
}
.nooitlijst li {
  position: relative; padding-left: 1.6rem;
  font-size: 0.9rem; color: var(--muted);
}
.nooitlijst li::before {
  content: "x";
  position: absolute; left: 0; top: 0.05rem;
  font-family: var(--mono); font-weight: 700; font-size: 0.85rem;
  color: var(--wr-bad);
}
.nooit-noot { margin: 1.2rem 0 0; font-size: 0.85rem; color: var(--dim); max-width: 72ch; }

/* ── Het ene ding dat wel verstuurd wordt ────────────────────────────────── */
.delen {
  margin-top: clamp(1.6rem, 3vw, 2.4rem);
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 0.75fr);
  gap: clamp(1.2rem, 3vw, 2.4rem);
  align-items: start;
  padding: 1.4rem 1.5rem;
  border: 1px solid var(--gold-dim);
  border-radius: var(--radius-s);
  background: rgba(231, 199, 110, 0.045);
}
@media (max-width: 860px) { .delen { grid-template-columns: 1fr; } }
.delen-label {
  margin: 0 0 0.45rem;
  font-family: var(--mono); font-size: 0.6rem; letter-spacing: 0.16em;
  text-transform: uppercase; color: var(--gold);
}
.delen-tekst h3 { margin: 0 0 0.8rem; font-size: 1.1rem; }
.delen-tekst p { margin: 0 0 0.75rem; font-size: 0.89rem; color: var(--muted); max-width: 68ch; }
.delen-tekst p:last-child { margin-bottom: 0; }
.delen-cijfer {
  padding: 1.1rem 1.2rem;
  border: 1px solid var(--line); border-radius: var(--radius-s);
  background: var(--raised);
}
.delen-cijfer b {
  display: block; font-family: var(--mono); font-size: 1.6rem; font-weight: 700;
  color: var(--gold); letter-spacing: -0.01em; font-variant-numeric: tabular-nums;
}
.delen-cijfer span {
  display: block; margin-top: 0.2rem;
  font-family: var(--mono); font-size: 0.6rem; letter-spacing: 0.13em;
  text-transform: uppercase; color: var(--dim);
}
.delen-cijfer p { margin: 0.7rem 0 0; font-size: 0.83rem; color: var(--muted); }

/* ── Zelf bouwen ─────────────────────────────────────────────────────────── */
.bouwzelf { margin-top: clamp(1.8rem, 3vw, 2.6rem); }
.bouwzelf h3 { margin: 0 0 0.6rem; font-size: 1.08rem; }
.bouwzelf > p { margin: 0 0 0.9rem; font-size: 0.9rem; color: var(--muted); }
.bouwzelf code { font-family: var(--mono); font-size: 0.83rem; color: var(--ink); }
.bouwcode {
  margin: 0; padding: 1rem 1.15rem; overflow-x: auto;
  border: 1px solid var(--line); border-radius: var(--radius-s);
  background: var(--ground);
  font-family: var(--mono); font-size: 0.83rem; line-height: 1.8; color: var(--gold-lit);
}
.bouw-noot { margin: 0.9rem 0 0; font-size: 0.86rem; color: var(--muted); max-width: 68ch; }
.bouw-noot a { color: var(--gold); text-decoration: none; border-bottom: 1px solid var(--gold-dim); }

/* ── De overlay-pagina ───────────────────────────────────────────────────── */
.gedraglijst {
  list-style: none; margin: 0; padding: 0;
  display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1px; background: var(--line); border: 1px solid var(--line);
  border-radius: var(--radius-s); overflow: hidden;
}
.gedraglijst li { padding: 1.1rem 1.2rem; background: var(--raised); font-size: 0.89rem; color: var(--muted); line-height: 1.62; }
.gedraglijst b { display: block; margin-bottom: 0.3rem; color: var(--ink); font-weight: 600; }

.tweekolom { display: grid; grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr); gap: clamp(1.3rem, 3vw, 2.4rem); align-items: start; }
@media (max-width: 880px) { .tweekolom { grid-template-columns: 1fr; } }

.timertabel { border: 1px solid var(--line); border-radius: var(--radius-s); padding: 1.2rem 1.3rem; background: rgba(255, 255, 255, 0.014); }
.timertabel h3 { margin: 0 0 0.9rem; font-size: 1.02rem; }
.timertabel table { width: 100%; border-collapse: collapse; }
.timertabel th {
  text-align: left; padding: 0 0 0.5rem;
  font-family: var(--mono); font-size: 0.58rem; font-weight: 500;
  letter-spacing: 0.14em; text-transform: uppercase; color: var(--dim);
  border-bottom: 1px solid var(--line);
}
.timertabel th:last-child, .timertabel td:last-child { text-align: right; }
.timertabel td { padding: 0.5rem 0; border-bottom: 1px solid var(--line); font-size: 0.9rem; color: var(--ink); }
.timertabel tbody tr:last-child td { border-bottom: 0; }
.timertabel td.mono { color: var(--gold); font-variant-numeric: tabular-nums; }
.timer-noot { margin: 0.9rem 0 0; font-size: 0.83rem; color: var(--dim); }
.timer-noot a { color: var(--gold); text-decoration: none; border-bottom: 1px solid var(--gold-dim); }

.eerlijk { border: 1px solid var(--line); border-left: 2px solid var(--gold-dim); border-radius: var(--radius-s); padding: 1.2rem 1.4rem; background: rgba(255, 255, 255, 0.014); }
.eerlijk h3 { margin: 0 0 0.7rem; font-size: 1.05rem; }
.eerlijk p { margin: 0 0 0.7rem; font-size: 0.89rem; color: var(--muted); max-width: 68ch; }
.eerlijk p:last-child { margin-bottom: 0; }
.eerlijk strong { color: var(--gold); font-weight: 600; }
.eerlijk code { font-family: var(--mono); font-size: 0.83rem; color: var(--ink); }

/* Rust: geen liften, geen gloedwissels die bewegen. Kleur blijft, want dat is
   toestand en geen beweging. */
@media (prefers-reduced-motion: reduce) {
  .btn-groot { transition: background var(--dur-fast) var(--ease-io); }
  .btn-groot:hover { transform: none; }
}

