/* ============================================================================
   PASTE INSTRUCTIONS — site/build.mjs

   (1) BLOCK A below: insert the whole block immediately BEFORE the line that reads

           const KENMERKEN = [

       (i.e. after leaguePagina() closes and before the "What the app actually
       does" comment block). Everything it uses — roster, champions, builds, esc,
       n, pct, laneLijst, iconOf, nameOf, wrClass, itemIcon, spellIcon, spellName,
       slugVan, SEED, T — is already defined in build.mjs and is only read at
       render time, so placement here is safe.

   (2) CALL SITE: inside leaguePagina(), find this exact pair of lines (it is the
       only place in the file where ${modusBalk()} is followed by the app band —
       the other ${modusBalk()} at ~line 3666 is followed by an HTML comment):

           ${modusBalk()}

           <section class="band" id="app">

       and change it to:

           ${modusBalk()}

           ${csSection()}

           <section class="band" id="app">

       csSection() emits its own <script id="cs-data"> and <script> at the end of
       the section, so there is no second call site and nothing else moves.

   (3) The new section renders as class="band alt", which keeps the existing
       band / band-alt alternation of the page intact below it.

   VERIFIED against the real data: 63 tiles, 296 ranked lane rows, every item and
   spell id resolves to a name, every matchup baseId resolves to a champion and an
   icon, spot-checked field-by-field against champions.json and builds.json,
   3,703 client-built rows contain no undefined/NaN, the client script parses, and
   the seed panel prints Tryndamere / Top / 58.0% over 12,397 games / rank #2 of
   63 — which is exactly what champions.json says. Section weight: 118 KB raw,
   37 KB gzipped, of which 81 KB is the inline payload.
   ========================================================================== */

/* ─────────────────────────── BLOCK A ─────────────────────────── */

/* ── Champion select, in the page ──────────────────────────────────────────
 *
 * The homepage claims the app fills your champion select in. This is that panel,
 * running in the page, on the real numbers -- pick anybody and it answers.
 *
 * Three rules it lives by:
 *  - Only ranked lanes. An unqualified lane has too few games to rank, and a demo
 *    that opens on a forty-game lane lies about the product.
 *  - Every tile is a real link to that champion's guide page. With the script off
 *    you get a complete panel for the seed champion and 63 working links -- no
 *    dead controls, because the two script-only controls (the filter and the lane
 *    tabs) are hidden in the markup and unhidden by the script.
 *  - Names go in with textContent, never into an HTML string: Riot ships
 *    "Doran's Ring" and "Kog'Maw", and an apostrophe in innerHTML is a bug
 *    waiting for the one champion nobody tested.
 */

/** How far either side of 50% fills the win-rate bar. Lane win rates live in a
 *  42-58 band; measuring from zero makes every champion look identical. */
const CS_SPAN = 8;

/** Only the lanes that carry enough games to be ranked. */
function csLaneRows(full) {
  return laneLijst(full).filter((r) => r.qualified);
}

/** The build row for one champion in one lane, straight out of builds.json. */
function csBuild(baseId, lane) {
  return builds.champions?.[String(baseId)]?.lanes?.find((x) => x.lane === lane) ?? null;
}

/** The lane the panel opens on: the most played of the ranked ones. */
function csOpenLane(full) {
  const rows = csLaneRows(full);
  if (!rows.length) return null;
  return rows.reduce((a, b) => (b.games > a.games ? b : a)).lane;
}

/** Bar geometry: how far the fill runs from the centre line. */
const csFill = (wr) => Math.min(100, (Math.abs(wr - 50) / CS_SPAN) * 100);

/**
 * The whole panel as numbers, small enough to sit in the page.
 *
 * Arrays, not objects: this is 296 lane rows, and a field name repeated 296
 * times is bytes the visitor pays for and never sees.
 *   champion -> [name, slug, totalGames, totalWinrate, lanes]
 *   lane     -> [games, winrate, rank, rankOf, pickRate, items, boots, spells, kda, beats, losesTo]
 */
function csData() {
  const items = {};
  const spells = {};
  const icons = {};
  const out = {};

  const rows = (list, k) =>
    (list ?? []).slice(0, k).map((x) => {
      items[x.baseId] = x.naam;
      return [x.baseId, x.pickRate, x.winrate];
    });
  const pair = (list) =>
    (list ?? []).slice(0, 1).map((x) => {
      spells[x.spells[0]] = spellName(x.spells[0]);
      spells[x.spells[1]] = spellName(x.spells[1]);
      return [x.spells[0], x.spells[1], x.pickRate, x.winrate];
    });
  const mu = (list) => (list ?? []).slice(0, 3).map((x) => [x.baseId, x.winrate, x.games]);

  for (const c of Object.values(roster)) {
    const full = champions.champions[String(c.baseId)];
    if (!full) throw new Error(`champions.json mist ${c.name} (${c.baseId})`);
    icons[c.baseId] = c.icon.path;

    const lanes = {};
    for (const r of csLaneRows(full)) {
      const b = csBuild(c.baseId, r.lane);
      lanes[r.lane] = [
        r.games,
        r.winrate,
        r.rank,
        r.rankOf,
        r.pickRate,
        rows(b?.items, 5),
        rows(b?.boots, 1),
        pair(b?.spells),
        b?.kda ? [b.kda.kills, b.kda.deaths, b.kda.assists, b.kda.ratio] : null,
        mu(r.beats),
        mu(r.losesTo),
      ];
    }
    // A champion with no ranked lane has nothing honest to show in a demo.
    if (!Object.keys(lanes).length) continue;
    out[c.baseId] = [c.name, slugVan(c.name), full.totalGames, full.winrate, lanes];
  }

  return { c: out, r: icons, i: items, s: spells };
}

/** The roster column: real links, alphabetical, the way you scan a lobby. */
function csGrid(seedId) {
  return Object.values(roster)
    .filter((c) => csLaneRows(champions.champions[String(c.baseId)]).length)
    .sort((a, b) => a.name.localeCompare(b.name))
    .map(
      (c) => `
          <a class="cs-tile" href="champion/${slugVan(c.name)}.html" data-champ="${c.baseId}"
             data-name="${esc(c.name.toLowerCase())}"${c.baseId === seedId ? ` aria-current="true"` : ""}>
            <img src="${c.icon.path}" alt="" width="128" height="128" loading="lazy" />
            <span class="cs-tile-name">${esc(c.name)}</span>
          </a>`,
    )
    .join("");
}

/** One item row. The same shape the script builds, so a swap changes nothing else. */
const csItemRow = (i) => `
            <li>
              <img src="${itemIcon(i.baseId)}" alt="" width="64" height="64" loading="lazy" />
              <span class="i-name">${esc(i.naam)}</span>
              <span class="i-pick">${pct(i.pickRate)}<small>%</small></span>
              <span class="i-wr ${wrClass(i.winrate)}">${pct(i.winrate)}<small>%</small></span>
            </li>`;

const csSpellRow = (s) => `
            <li>
              <span class="s-pair">
                <img src="${spellIcon(s.spells[0])}" alt="" width="64" height="64" loading="lazy" />
                <img src="${spellIcon(s.spells[1])}" alt="" width="64" height="64" loading="lazy" />
              </span>
              <span class="i-name">${esc(spellName(s.spells[0]))} + ${esc(spellName(s.spells[1]))}</span>
              <span class="i-pick">${pct(s.pickRate)}<small>%</small></span>
              <span class="i-wr ${wrClass(s.winrate)}">${pct(s.winrate)}<small>%</small></span>
            </li>`;

const csMuRow = (m, up) => `
            <li>
              <img src="${iconOf(m.baseId)}" alt="" width="128" height="128" loading="lazy" />
              <span class="m-name">${esc(m.name ?? nameOf(m.baseId))}</span>
              <span class="m-games">${n(m.games)}g</span>
              <span class="m-wr ${up ? "wr-hi" : "wr-bad"}">${pct(m.winrate)}<small>%</small></span>
            </li>`;

/**
 * The panel itself, pre-filled with one champion.
 *
 * Rendered on the server so the section is a finished, readable block of real
 * data before a byte of script has run. The script writes into exactly these
 * ids and rebuilds exactly these rows.
 */
function csPanel(seedId) {
  const full = champions.champions[String(seedId)];
  const rows = csLaneRows(full);
  const lane = csOpenLane(full);
  const row = rows.find((r) => r.lane === lane) ?? rows[0];
  const b = csBuild(seedId, row.lane);
  const kda = b?.kda ?? null;
  const empty = `<li class="c-empty">Not enough games.</li>`;

  return `
      <div class="cs-panel" id="cs-panel">
        <div class="cs-head">
          <img class="cs-portrait" id="cs-portrait" src="${iconOf(seedId)}" alt="" width="128" height="128" />
          <div class="cs-ident">
            <h3 id="cs-name">${esc(nameOf(seedId))}</h3>
