          </div>
          <a class="btn btn-ghost btn-sm cs-guide" id="cs-guide" href="champion/${slugVan(nameOf(seedId))}.html">Full build</a>
        </div>

        <div class="lane-tabs cs-lanes" id="cs-lanes" role="tablist" aria-label="Lane" hidden>
          ${rows
            .map(
              (r) =>
                `<button type="button" role="tab" id="cs-tab-${r.lane}" data-lane="${r.lane}"` +
                ` aria-selected="${r.lane === row.lane}" tabindex="${r.lane === row.lane ? "0" : "-1"}">` +
                `${esc(r.label)}<span>${pct(r.winrate)}%</span></button>`,
