          <a href="champion/${slugVan(nameOf(seedId))}.html">See every lane</a>
        </p>

        <div class="cs-body" id="cs-body">
          <div class="cs-stats">
            <div class="cs-stat cs-stat-wr">
              <span class="cs-stat-label">Win rate</span>
              <b class="cs-wr ${wrClass(row.winrate)}" id="cs-wr">${pct(row.winrate)}<small>%</small></b>
              <div class="cs-bar" id="cs-bar" data-dir="${row.winrate >= 50 ? "up" : "down"}" aria-hidden="true">
                <span class="cs-bar-fill" style="--fill:${csFill(row.winrate).toFixed(1)}%"></span>
              </div>
              <span class="cs-stat-sub" id="cs-wr-games">over ${n(row.games)} games</span>
            </div>
            <div class="cs-stat">
              <span class="cs-stat-label">Lane rank</span>
              <b id="cs-rank">#${row.rank}</b>
              <span class="cs-stat-sub" id="cs-rank-sub">of ${row.rankOf} ranked</span>
            </div>
            <div class="cs-stat">
              <span class="cs-stat-label">Pick rate</span>
