            </div>
            <div class="cs-stat">
              <span class="cs-stat-label">Average KDA</span>
              <b id="cs-kda">${kda ? `${pct(kda.kills)}<small>/</small>${pct(kda.deaths)}<small>/</small>${pct(kda.assists)}` : "&mdash;"}</b>
              <span class="cs-stat-sub" id="cs-kda-sub">${kda ? `${pct(kda.ratio)} ratio` : "no build data"}</span>
            </div>
          </div>

          <div class="cs-cols">
            <div>
              <p class="block-label">Most built <span>end of game</span></p>
