            </div>
            <div>
              <p class="block-label">Boots</p>
              <ul class="itemlist" id="cs-boots">${(b?.boots ?? []).slice(0, 1).map(csItemRow).join("") || empty}</ul>
              <p class="block-label cs-label-gap">Summoner spells</p>
              <ul class="itemlist" id="cs-spells">${(b?.spells ?? []).slice(0, 1).map(csSpellRow).join("") || empty}</ul>
            </div>
            <div>
              <p class="block-label">Wins into</p>
              <ul class="matchups" id="cs-beats">${
                (row.beats ?? [])
                  .slice(0, 3)
