      </div>`;
}

/**
 * The one script this section needs.
 *
 * No template literals and no backticks: this string is itself inside a template
 * literal in the generator. Concatenation only.
 */
const CS_SCRIPT = `<script>
(function () {
  "use strict";

  var root = document.getElementById("cs");
  var store = document.getElementById("cs-data");
  if (!root || !store) return;

  var D = JSON.parse(store.textContent);
  var LANE_ORDER = ["TOP", "JUNGLE", "MIDDLE", "BOTTOM", "SUPPORT"];
  var LANE_LABEL = { TOP: "Top", JUNGLE: "Jungle", MIDDLE: "Mid", BOTTOM: "Bot", SUPPORT: "Support" };
  var SPAN = 8;

  var el = function (id) { return document.getElementById(id); };
  var num = function (v) { return Number(v).toLocaleString("en-US"); };
  var pct = function (v) { return Number(v).toFixed(1); };
  var wrClass = function (wr) { return wr >= 54 ? "wr-hi" : wr >= 50 ? "wr-ok" : wr >= 46 ? "wr-lo" : "wr-bad"; };
  var fill = function (wr) { return Math.min(100, (Math.abs(wr - 50) / SPAN) * 100).toFixed(1) + "%"; };

  var grid = el("cs-grid");
  var tabs = el("cs-lanes");
  var body = el("cs-body");
  var panel = el("cs-panel");
  var status = el("cs-status");
  var searchWrap = el("cs-search-wrap");
  var search = el("cs-search");
  var count = el("cs-count");
  var empty = el("cs-empty");
  var laneStatic = el("cs-lane-static");
  if (!grid || !tabs || !body || !panel) return;

  var tiles = [].slice.call(grid.querySelectorAll(".cs-tile"));
  var current = null;

  // The two script-only controls now have a script. Until this line they are
  // hidden, so a visitor without JavaScript never meets a button that does nothing --
  // and the panel below is a tabpanel only once there is a tablist to label it.
  tabs.hidden = false;
  body.setAttribute("role", "tabpanel");
  body.setAttribute("tabindex", "0");
  if (searchWrap) searchWrap.hidden = false;
  if (laneStatic) laneStatic.hidden = true;

  /* ── Row builders. Names via textContent; Riot ships apostrophes. ── */

  function line(iconHtml, name, pick, wr) {
    var li = document.createElement("li");
    li.innerHTML =
      iconHtml +
      '<span class="i-name"></span>' +
      '<span class="i-pick">' + pct(pick) + "<small>%</small></span>" +
      '<span class="i-wr ' + wrClass(wr) + '">' + pct(wr) + "<small>%</small></span>";
    li.querySelector(".i-name").textContent = name;
    return li.outerHTML;
  }

  var img = function (src, size) {
    return '<img src="' + src + '" alt="" width="' + size + '" height="' + size + '" loading="lazy" />';
  };
  var itemImg = function (id) { return img("img/items/" + id + ".png", 64); };
  var spellImg = function (id) { return img("img/spells/" + id + ".png", 64); };

  function itemRow(r) { return line(itemImg(r[0]), D.i[r[0]] || "Item " + r[0], r[1], r[2]); }

  function spellRow(r) {
    return line(
      '<span class="s-pair">' + spellImg(r[0]) + spellImg(r[1]) + "</span>",
      (D.s[r[0]] || r[0]) + " + " + (D.s[r[1]] || r[1]),
      r[2],
      r[3]
    );
  }

  function muRow(r, up) {
    var c = D.c[r[0]];
    var li = document.createElement("li");
    li.innerHTML =
      img(D.r[r[0]] || "", 128) +
      '<span class="m-name"></span>' +
      '<span class="m-games">' + num(r[2]) + "g</span>" +
      '<span class="m-wr ' + (up ? "wr-hi" : "wr-bad") + '">' + pct(r[1]) + "<small>%</small></span>";
    li.querySelector(".m-name").textContent = c ? c[0] : r[0];
    return li.outerHTML;
  }

  function listInto(node, list, make, emptyText) {
    node.innerHTML = list.length
      ? list.map(make).join("")
      : '<li class="c-empty">' + emptyText + "</li>";
  }

  /* ── Lane tabs ── */

  function mainLane(champ) {
    var lanes = champ[4];
    var best = null;
    for (var i = 0; i < LANE_ORDER.length; i++) {
      var k = LANE_ORDER[i];
      if (lanes[k] && (!best || lanes[k][0] > lanes[best][0])) best = k;
    }
    return best;
  }

  function drawTabs(champ, lane) {
    var lanes = champ[4];
    var want = LANE_ORDER.filter(function (k) { return lanes[k]; });
    var have = [].slice.call(tabs.querySelectorAll("button"));
    // Rebuild only when the set of lanes actually differs. The comparison has to
    // hold BOTH ways: "every old button is still wanted" alone leaves a champion
    // with more lanes wearing the previous champion's shorter set of tabs.
    var same = have.length === want.length && have.every(function (b, i) { return b.dataset.lane === want[i]; });

    if (!same) {
      tabs.innerHTML = want
        .map(function (k) {
          return '<button type="button" role="tab" id="cs-tab-' + k + '" data-lane="' + k + '">' +
            LANE_LABEL[k] + "<span>" + pct(lanes[k][1]) + "%</span></button>";
        })
        .join("");
    } else {
      have.forEach(function (b) {
        b.querySelector("span").textContent = pct(lanes[b.dataset.lane][1]) + "%";
      });
    }

    [].slice.call(tabs.querySelectorAll("button")).forEach(function (b) {
      var on = b.dataset.lane === lane;
      b.setAttribute("aria-selected", String(on));
      b.tabIndex = on ? 0 : -1;
    });
    body.setAttribute("aria-labelledby", "cs-tab-" + lane);
  }

  /* ── The panel ── */

  function show(id, lane, announce) {
    var champ = D.c[id];
    if (!champ) return;
    var lanes = champ[4];
    var key = lane && lanes[lane] ? lane : mainLane(champ);
    if (!key) return;
    var L = lanes[key];

    current = String(id);

    el("cs-portrait").src = D.r[id] || "";
    el("cs-name").textContent = champ[0];
    el("cs-meta").textContent =
      num(champ[2]) + " games recorded \\u00b7 " + pct(champ[3]) + "% across every lane";

    var guide = el("cs-guide");
    guide.href = "champion/" + champ[1] + ".html";
    guide.setAttribute("aria-label", "Full build for " + champ[0]);

    var wr = el("cs-wr");
    wr.className = "cs-wr " + wrClass(L[1]);
    wr.innerHTML = pct(L[1]) + "<small>%</small>";
    var barEl = el("cs-bar");
    barEl.dataset.dir = L[1] >= 50 ? "up" : "down";
    barEl.firstElementChild.style.setProperty("--fill", fill(L[1]));
    el("cs-wr-games").textContent = "over " + num(L[0]) + " games";

    el("cs-rank").textContent = "#" + L[2];
    el("cs-rank-sub").textContent = "of " + L[3] + " ranked";
    el("cs-pick").innerHTML = pct(L[4]) + "<small>%</small>";

    var kda = L[8];
    el("cs-kda").innerHTML = kda
      ? pct(kda[0]) + "<small>/</small>" + pct(kda[1]) + "<small>/</small>" + pct(kda[2])
      : "&mdash;";
    el("cs-kda-sub").textContent = kda ? pct(kda[3]) + " ratio" : "no build data";

    listInto(el("cs-items"), L[5], itemRow, "Not enough games.");
    listInto(el("cs-boots"), L[6], itemRow, "Not enough games.");
    listInto(el("cs-spells"), L[7], spellRow, "Not enough games.");
    listInto(el("cs-beats"), L[9], function (r) { return muRow(r, true); }, "No winning matchup in this lane.");
    listInto(el("cs-loses"), L[10], function (r) { return muRow(r, false); }, "No losing matchup in this lane.");

    drawTabs(champ, key);

    tiles.forEach(function (t) {
      if (t.dataset.champ === current) t.setAttribute("aria-current", "true");
      else t.removeAttribute("aria-current");
    });

    // Restart the swap animation. Dropping the class and reading offsetWidth is
    // what makes it run a second time on a second pick.
    panel.classList.remove("cs-swap");
    void panel.offsetWidth;
    panel.classList.add("cs-swap");

    if (announce && status) {
      status.textContent =
        champ[0] + ", " + LANE_LABEL[key] + ": " + pct(L[1]) + "% win rate over " +
        num(L[0]) + " games, ranked " + L[2] + " of " + L[3] + ".";
    }
  }

  /* ── Picking a champion ── */

  grid.addEventListener("click", function (e) {
    var tile = e.target.closest ? e.target.closest(".cs-tile") : null;
    if (!tile || !grid.contains(tile)) return;
    // Ctrl/cmd/shift click still opens the guide page, the way a link should.
    if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return;
    e.preventDefault();
    show(tile.dataset.champ, null, true);
  });

  function visible() {
    return tiles.filter(function (t) { return !t.hidden; });
  }

  // Arrow keys walk the grid the way the eye does. The column count is read off
  // the laid-out tiles, so it stays right at every breakpoint.
  grid.addEventListener("keydown", function (e) {
    if (["ArrowRight", "ArrowLeft", "ArrowDown", "ArrowUp", "Home", "End"].indexOf(e.key) === -1) return;
    var open = visible();
    var i = open.indexOf(document.activeElement);
    if (i === -1) return;
    var top = open[0].offsetTop;
    var cols = 0;
    while (cols < open.length && open[cols].offsetTop === top) cols++;
    cols = Math.max(1, cols);

    var next = i;
    if (e.key === "ArrowRight") next = Math.min(open.length - 1, i + 1);
    if (e.key === "ArrowLeft") next = Math.max(0, i - 1);
    if (e.key === "ArrowDown") next = Math.min(open.length - 1, i + cols);
    if (e.key === "ArrowUp") next = Math.max(0, i - cols);
    if (e.key === "Home") next = 0;
    if (e.key === "End") next = open.length - 1;
    if (next === i) return;
    e.preventDefault();
    open[next].focus();
  });

  /* ── Lane tabs: the standard tablist keyboard, roving tabindex and all ── */

  tabs.addEventListener("click", function (e) {
    var b = e.target.closest ? e.target.closest("button") : null;
    if (!b || !tabs.contains(b)) return;
    show(current, b.dataset.lane, true);
  });

  tabs.addEventListener("keydown", function (e) {
    var order = [].slice.call(tabs.querySelectorAll("button"));
    var i = order.indexOf(document.activeElement);
    if (i === -1) return;
    var next = i;
    if (e.key === "ArrowRight") next = (i + 1) % order.length;
    else if (e.key === "ArrowLeft") next = (i - 1 + order.length) % order.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = order.length - 1;
    else return;
    e.preventDefault();
    var lane = order[next].dataset.lane;
    show(current, lane, true);
    // show() rebuilt the tabs, so the node to focus is looked up again.
    var moved = tabs.querySelector('button[data-lane="' + lane + '"]');
    if (moved) moved.focus();
  });

  /* ── Filtering ── */

  if (search && count && empty) {
    var filter = function () {
      var q = search.value.trim().toLowerCase();
      var shown = 0;
      tiles.forEach(function (t) {
        var hit = !q || t.dataset.name.indexOf(q) !== -1;
        t.hidden = !hit;
        if (hit) shown++;
      });
      empty.hidden = shown !== 0;
      count.textContent = q
        ? shown + (shown === 1 ? " champion matches" : " champions match")
        : tiles.length + " champions with Classic games";
    };

    search.addEventListener("input", filter);
    search.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && search.value) {
        e.preventDefault();
        search.value = "";
        filter();
        return;
      }
      if (e.key !== "Enter") return;
      e.preventDefault();
      // Enter takes the best match: a name that STARTS with what you typed beats
      // one that merely contains it, so "ka" lands on Kayle, not Blitzcrank.
      var q = search.value.trim().toLowerCase();
      var open = visible();
      if (!open.length) return;
      var starts = open.filter(function (t) { return t.dataset.name.indexOf(q) === 0; });
      var pick = starts.length ? starts[0] : open[0];
      show(pick.dataset.champ, null, true);
      pick.scrollIntoView({ block: "nearest" });
    });
  }

  // Adopt the server-rendered panel instead of redrawing it: the markup is
  // already correct, and a first paint that flickers is worse than no script.
  var seed = grid.querySelector('.cs-tile[aria-current="true"]') || tiles[0];
  if (seed) {
    current = seed.dataset.champ;
    var seedChamp = D.c[current];
    if (seedChamp) drawTabs(seedChamp, mainLane(seedChamp));
  }
})();
</script>`;

/**
 * The whole section: roster on the left, panel on the right, data and script
 * underneath. One call site, so nothing else in leaguePagina() has to move.
 */
function csSection() {
  const seedId = SEED;
  const payload = JSON.stringify(csData()).replace(/</g, "\\u003c");
  const covered = Object.values(roster).filter(
    (c) => csLaneRows(champions.champions[String(c.baseId)]).length,
  ).length;

  return `
<section class="band alt" id="try">
  <div class="wrap rise">
    <div class="sectiekop">
      <p class="eyebrow">Try it here</p>
      <h2>This is the panel it puts on your champion select. Pick any of the 63.</h2>
      <p class="sectielede">
        Not a screenshot and not a mock-up &mdash; the same ${n(T.games)} games, answering in the
        page. Choose a champion, choose a lane, and you get what the app hands you the moment you
        lock in: what wins, what you beat, and what beats you, with the sample size on every line.
      </p>
    </div>

    <div class="cs" id="cs">
      <div class="cs-picker">
        <div class="cs-search" id="cs-search-wrap" hidden>
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7" /><path d="m20 20-3.6-3.6" /></svg>
          <input id="cs-search" type="search" autocomplete="off" spellcheck="false"
                 placeholder="Type a champion" aria-label="Filter champions" aria-controls="cs-grid" />
        </div>
        <p class="cs-count" id="cs-count">${covered} champions with Classic games</p>
        <div class="cs-grid" id="cs-grid">${csGrid(seedId)}</div>
        <p class="cs-empty" id="cs-empty" hidden>No champion by that name in Classic.</p>
      </div>

      ${csPanel(seedId)}
    </div>

    <p class="cs-sr" id="cs-status" role="status" aria-live="polite"></p>
  </div>
</section>

<script id="cs-data" type="application/json">${payload}</script>
${CS_SCRIPT}`;
}

