css:
/* PASTE: append at the very end of the `css` template literal in site/build.mjs —
   immediately before the closing line that reads

       `;
       writeFileSync(join(HERE, "style.css"), css, "utf8");

   i.e. after the final "}" of the existing prefers-reduced-motion block that ends
   with `.secties a:not([aria-current="page"]):hover::after { transform: scaleX(0); opacity: 0; }`.
