/* ── Champion select, in the page ────────────────────────────────────────────
   The one place on the home page where the visitor drives. Roster on the left,
   the app's own panel on the right; below 1080px the roster folds into a short
   scrolling band above it. Existing tokens only, and every transform sits behind
   prefers-reduced-motion. */

.cs {
  display: grid;
  grid-template-columns: minmax(240px, 320px) minmax(0, 1fr);
  gap: 1.1rem;
  align-items: start;
}

/* ── The roster column ── */

.cs-picker {
  display: grid;
  gap: 0.6rem;
  padding: 0.85rem;
  border: 1px solid var(--line-lit);
  border-radius: var(--radius);
  background: var(--surface);
}

/* Author display beats the UA rule for [hidden], so both script-only controls
   need it spelled out. Without this the lane tabs render for a visitor whose
   script never ran, as buttons that cannot do anything. */
.cs-search[hidden], .cs-lanes[hidden] { display: none; }

.cs-search { position: relative; display: flex; align-items: center; }
.cs-search svg {
  position: absolute; left: 0.72rem; width: 15px; height: 15px;
  color: var(--dim); pointer-events: none;
}
.cs-search input {
  width: 100%; font: inherit; font-size: 0.9rem; color: var(--ink);
  padding: 0.55rem 0.7rem 0.55rem 2.05rem;
  background: var(--ground); border: 1px solid var(--line); border-radius: var(--radius-s);
  transition: border-color var(--dur-mid) var(--ease-io), box-shadow var(--dur-mid) var(--ease-io);
}
.cs-search input::placeholder { color: var(--dim); }
.cs-search input:focus { outline: none; border-color: var(--gold-dim); box-shadow: var(--ring-gold); }
.cs-search input::-webkit-search-cancel-button { filter: grayscale(1) opacity(0.55); }

.cs-count {
  margin: 0; font-family: var(--mono); font-size: 0.62rem; letter-spacing: 0.11em;
  text-transform: uppercase; color: var(--dim);
}
.cs-empty { margin: 0; font-size: 0.8rem; color: var(--muted); font-style: italic; }

.cs-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(64px, 1fr));
  gap: 0.3rem;
  max-height: 27rem;
  overflow-y: auto;
  padding-right: 0.15rem;
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  scrollbar-color: var(--line-lit) transparent;
}
.cs-grid::-webkit-scrollbar { width: 8px; }
.cs-grid::-webkit-scrollbar-track { background: transparent; }
.cs-grid::-webkit-scrollbar-thumb { background: var(--line-lit); border-radius: 4px; }

.cs-tile {
  display: grid; justify-items: center; gap: 0.22rem;
  padding: 0.35rem 0.15rem 0.4rem;
  text-decoration: none;
  border: 1px solid transparent; border-radius: var(--radius-s);
  transition: background-color var(--dur-fast) var(--ease-io),
              border-color var(--dur-fast) var(--ease-io);
}
.cs-tile[hidden] { display: none; }
.cs-tile img { width: 40px; height: 40px; border-radius: 6px; border: 1px solid var(--line); }
.cs-tile-name {
  max-width: 100%; font-size: 0.6rem; color: var(--dim);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.cs-tile:hover { background: var(--raised); border-color: var(--line-lit); }
.cs-tile:hover .cs-tile-name { color: var(--ink); }
.cs-tile[aria-current="true"] { background: rgba(231, 199, 110, 0.09); border-color: var(--gold-dim); }
.cs-tile[aria-current="true"] img { border-color: var(--gold-dim); }
.cs-tile[aria-current="true"] .cs-tile-name { color: var(--gold); }

/* ── The panel ── */

.cs-panel {
  border: 1px solid var(--line-lit); border-radius: var(--radius);
  background: var(--surface); box-shadow: var(--shadow);
  overflow: hidden;
}

.cs-head {
  display: flex; align-items: center; gap: 0.85rem;
  padding: 0.9rem 1.1rem;
  background: var(--raised); border-bottom: 1px solid var(--line);
}
.cs-portrait { flex: none; width: 46px; height: 46px; border-radius: 8px; border: 1px solid var(--gold-dim); }
.cs-ident { min-width: 0; }
.cs-ident h3 { margin: 0; font-size: 1.18rem; }
.cs-meta { margin: 0.12rem 0 0; font-family: var(--mono); font-size: 0.68rem; color: var(--dim); }
.cs-guide { flex: none; margin-left: auto; }

.cs-lanes { padding: 0.9rem 1.1rem 0; margin-bottom: 0; }
.cs-lanes button span { margin-left: 0.42rem; font-size: 0.92em; color: var(--dim); }
.cs-lanes button[aria-selected="true"] span { color: var(--gold-dim); }

/* Shown only while the script is absent: the panel then covers one lane, and
   says so rather than leaving a switcher that cannot switch. */
.cs-lane-static { margin: 0; padding: 0.9rem 1.1rem 0; font-size: 0.85rem; color: var(--muted); }
.cs-lane-static strong { color: var(--gold); }

.cs-body { padding: 1.1rem; }
.cs-body:focus-visible { outline: 2px solid var(--gold); outline-offset: -5px; border-radius: 4px; }

.cs-stats {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0.9rem;
  padding-bottom: 1.05rem; margin-bottom: 1.05rem; border-bottom: 1px solid var(--line);
}
/* Colour is inherited, never set on the <b>: the win-rate class on that element
   has to win, and an element+class selector here would outrank it. */
.cs-stat { display: grid; align-content: start; gap: 0.22rem; color: var(--ink); }
.cs-stat-label {
  font-family: var(--mono); font-size: 0.57rem; letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--dim);
}
.cs-stat b {
  font-family: var(--mono); font-weight: 700; font-size: 1.35rem; line-height: 1;
  font-variant-numeric: tabular-nums;
}
.cs-stat b small { font-size: 0.55em; opacity: 0.62; margin-left: 1px; }
.cs-stat-sub { font-family: var(--mono); font-size: 0.65rem; color: var(--dim); }
.cs-stat-wr b { font-size: 1.85rem; }

/* Fifty per cent is the origin, not zero: lane win rates live between 42 and 58,
   and a bar measured from zero makes all of them the same length. */
.cs-bar {
  position: relative; height: 6px; margin: 0.34rem 0 0.12rem;
  background: var(--ground); border: 1px solid var(--line); border-radius: 3px;
}
.cs-bar::before {
  content: ""; position: absolute; left: 50%; top: -2px; bottom: -2px;
  width: 1px; background: var(--line-lit);
}
.cs-bar-fill { position: absolute; top: 0; bottom: 0; width: calc(var(--fill, 0%) / 2); border-radius: 2px; }
.cs-bar[data-dir="up"] .cs-bar-fill { left: 50%; background: var(--wr-hi); }
.cs-bar[data-dir="down"] .cs-bar-fill { right: 50%; background: var(--wr-bad); }

.cs-cols { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.3rem; }
.cs-label-gap { margin-top: 1.15rem; }

.cs-foot {
  margin: 0; padding: 0.85rem 1.1rem;
  border-top: 1px solid var(--line); background: rgba(255, 255, 255, 0.014);
  font-size: 0.74rem; line-height: 1.55; color: var(--dim);
}

/* The panel changes without the page moving, so screen readers get told. */
.cs-sr {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0;
}

@media (prefers-reduced-motion: no-preference) {
  .cs-tile { transition: background-color var(--dur-fast) var(--ease-io),
                         border-color var(--dur-fast) var(--ease-io),
                         transform var(--dur-fast) var(--ease-out); }
  .cs-tile:hover { transform: translateY(-1px); }
  .cs-bar-fill { transition: width var(--dur-mid) var(--ease-out), background-color var(--dur-mid) var(--ease-io); }
  .cs-swap .cs-stats, .cs-swap .cs-cols { animation: cs-in var(--dur-mid) var(--ease-out) both; }
  .cs-swap .cs-cols { animation-delay: 40ms; }
  @keyframes cs-in {
    from { opacity: 0; transform: translateY(5px); }
    to   { opacity: 1; transform: none; }
  }
}

@media (max-width: 1080px) {
  .cs { grid-template-columns: minmax(0, 1fr); }
  .cs-grid { max-height: 13.5rem; grid-template-columns: repeat(auto-fill, minmax(62px, 1fr)); }
}

@media (max-width: 760px) {
  .cs-head { flex-wrap: wrap; }
  .cs-guide { width: 100%; margin-left: 0; text-align: center; }
  .cs-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .cs-cols { grid-template-columns: minmax(0, 1fr); gap: 1.05rem; }
  .cs-stat-wr b { font-size: 1.6rem; }
}

