/* ── Catalogue pages: the 110 without a single Classic game ───────────────────
 *
 * Two thirds of the roster never existed in Season 3, so two thirds of these
 * pages can never carry a win rate. They used to say so in four paragraphs and
 * then print six base stats, which is a page that apologises and stops. Riot's
 * published numbers are still facts, and there are two honest things to do with
 * them: say where this champion sits among all 173, and point at the champions
 * Classic does have that stand closest to the same profile -- with their real
 * numbers attached and a link, so the page ends somewhere instead of nowhere.
 * ───────────────────────────────────────────────────────────────────────────── */

const STAT_VELDEN = [
  { k: "hp", label: "Health", groei: "hpPerLevel" },
  { k: "ad", label: "Attack damage", groei: "adPerLevel" },
  { k: "armor", label: "Armor", groei: "armorPerLevel" },
  { k: "mr", label: "Magic resist", groei: "mrPerLevel" },
  { k: "moveSpeed", label: "Move speed", groei: null },
  { k: "range", label: "Attack range", groei: null },
];

/** Sorted values per stat over the whole roster, so any value can be placed in it. */
const STAT_INDEX = (() => {
  const out = {};
  for (const { k } of STAT_VELDEN) {
    out[k] = catalogus.champions
      .map((c) => c.stats?.[k])
      .filter((v) => typeof v === "number")
      .sort((a, b) => a - b);
  }
  return out;
})();

/** Rank (1 = highest) and percentile of one published value among all champions. */
function statPositie(k, v) {
  const arr = STAT_INDEX[k];
  if (!arr?.length || typeof v !== "number") return null;
  let lager = 0;
  let gelijk = 0;
  for (const x of arr) {
    if (x < v) lager++;
    else if (x === v) gelijk++;
  }
  return {
    rang: arr.length - lager - gelijk + 1,
    van: arr.length,
    deel: Math.round(((lager + gelijk / 2) / arr.length) * 100),
  };
}

/**
 * Base stats with a position instead of a bare number.
 *
 * "Armor 38" is unreadable unless you carry all 173 in your head. "38, 9th of
 * 173" is a fact about the same value that anybody can use immediately.
 */
function catStatBalk(c) {
  const st = c.stats ?? {};
  const rijen = STAT_VELDEN.map(({ k, label, groei }) => {
    const v = st[k];
    if (typeof v !== "number") {
      return `<div class="csr"><span class="csr-label">${esc(label)}</span><b class="csr-waarde">&mdash;</b><span class="csr-balk"></span><span class="csr-rang"></span></div>`;
    }
    const p = statPositie(k, v);
    const per = groei && st[groei] ? `<span class="csr-groei">+${st[groei]}/lvl</span>` : "";
    return `
        <div class="csr">
          <span class="csr-label">${esc(label)}</span>
          <b class="csr-waarde">${Math.round(v) === v ? v : v.toFixed(2)}${per}</b>
          <span class="csr-balk"><i style="width:${p ? p.deel : 0}%"></i></span>
          <span class="csr-rang">#${p.rang}<span> of ${p.van}</span></span>
        </div>`;
  }).join("");

  return `
  <section class="guide-blok">
    <h2>Where ${esc(c.name)} sits in the roster</h2>
    <p>
      Riot&rsquo;s own published base values, patch ${esc(catalogus.version ?? "&mdash;")}, at level&nbsp;1
      before items &mdash; each one ranked against all ${n(STAT_INDEX.hp?.length ?? 0)} champions in the
      game. A rank is a position, not a verdict: high base health says what the champion starts with
      and nothing about whether it is good.
    </p>
    <div class="cat-statrijen">${rijen}</div>
  </section>`;
}

/* Six published numbers put on one scale, so the distance between two champions
   means something. Range is the split that matters most -- a 125 melee and a 550
   marksman are not neighbours whatever else they share -- so it is not damped. */
const PROFIEL = ["hp", "ad", "armor", "mr", "moveSpeed", "range"];
const PROFIEL_NORM = (() => {
  const out = {};
  for (const k of PROFIEL) {
    const v = catalogus.champions.map((c) => c.stats?.[k]).filter((x) => typeof x === "number");
    const gem = v.reduce((a, b) => a + b, 0) / v.length;
    const sd = Math.sqrt(v.reduce((a, b) => a + (b - gem) ** 2, 0) / v.length) || 1;
    out[k] = { gem, sd };
  }
  return out;
})();
const zScore = (k, v) => (v - PROFIEL_NORM[k].gem) / PROFIEL_NORM[k].sd;

/** The catalogue entries of the 63 champions Classic actually has. */
const CLASSIC_CAT = catalogus.champions.filter((c) => IN_CLASSIC.has(c.id));

/**
 * The champions Classic does have that stand closest to this one.
 *
 * Explicitly not a claim that they play alike, and the page says so: it is
 * Riot's class tags plus the distance between two sets of published base stats.
 * What it buys is that a page with no data of its own still ends at four real
 * numbers somebody can use, on four pages that do have data.
 */
function catVerwanten(c, hoeveel = 4) {
  if (!c.stats || !CLASSIC_CAT.length) return [];
  const mijn = new Set(c.tags ?? []);
  return CLASSIC_CAT.map((o) => {
    let d = 0;
    for (const k of PROFIEL) {
      const a = c.stats[k];
      const b = o.stats?.[k];
      if (typeof a !== "number" || typeof b !== "number") continue;
      d += (zScore(k, a) - zScore(k, b)) ** 2;
    }
    const gedeeld = (o.tags ?? []).filter((t) => mijn.has(t));
    // Sharing no class at all is a bigger difference than any stat gap.
    const straf = gedeeld.length === 0 ? 9 : gedeeld.length === 1 ? 2 : 0;
    return { o, afstand: Math.sqrt(d + straf), gedeeld };
  })
    .sort((a, b) => a.afstand - b.afstand)
    .slice(0, hoeveel)
    .map(({ o, gedeeld }) => {
      const stat = champions.champions[String(o.id)];
      if (!stat) return null;
      const lanes = laneLijst(stat).filter((r) => r.games > 0);
      const vaakst = lanes.length ? lanes.reduce((a, b) => (b.games > a.games ? b : a)) : null;
      return {
        baseId: o.id,
        name: o.name,
        tags: o.tags ?? [],
        gedeeld,
        winrate: stat.winrate,
        games: stat.totalGames,
        lane: vaakst,
      };
    })
    .filter(Boolean);
}

function catVerwantenBlok(c) {
  const lijst = catVerwanten(c);
  if (!lijst.length) return "";
  const kaarten = lijst
    .map(
      (v) => `
        <a class="verwant" href="${paginaHref(v.baseId)}">
          <img src="${G(iconOf(v.baseId))}" alt="" width="128" height="128" loading="lazy" />
          <span class="v-naam">${esc(v.name)}</span>
          <span class="v-tags">${esc(v.tags.join(" / "))}</span>
          <span class="v-wr ${wrClass(v.winrate)}">${pct(v.winrate)}<small>%</small></span>
          <span class="v-meta">${n(v.games)} games${v.lane ? ` &middot; mostly ${esc(v.lane.label.toLowerCase())}` : ""}</span>
        </a>`,
    )
    .join("");

  const tags = (c.tags ?? []).join(" / ");
  return `
  <section class="guide-blok blok-verwant">
    <h2>The closest thing Classic has</h2>
    <p>
      ${esc(c.name)} has no Classic games, so here is the most useful true thing left to say: the
      champions Classic <em>does</em> have that stand nearest to Riot&rsquo;s own description of
      ${esc(c.name)} &mdash; ${esc(tags || "the same class")}, and the six published base stats. The win
      rates below are measured, out of ${n(T.games)} recorded games.
    </p>
    <div class="verwanten">${kaarten}</div>
    <p class="verwanten-note">
      A stat neighbour is not a playstyle match and should not be read as one. It is Riot&rsquo;s class
      tags plus the distance between two sets of base stats &mdash; a way into &ldquo;what does this
      kind of champion do in Classic&rdquo;, not a stand-in for data on this one.
    </p>
  </section>`;
}

