          <p class="block-label">Boots</p>
          ${lijstKop(basis)}
          <ul class="itemlist">${(buildRegel?.boots ?? []).map((i) => gItemRij(i, basis)).join("") || leeg}</ul>

          <p class="block-label">Starting items</p>
          ${lijstKop(basis)}
          <ul class="itemlist">${(buildRegel?.starters ?? []).map((i) => gItemRij(i, basis)).join("") || leeg}</ul>

          <p class="block-label">Summoner spells</p>
          ${lijstKop(basis, "taken")}
          <ul class="itemlist">${(buildRegel?.spells ?? []).map((sp) => gSpelRij(sp, basis)).join("") || leeg}</ul>
        </div>

        <div>
          <p class="block-label">Wins into</p>
          <ul class="matchups is-link">${(laneRegel.beats ?? []).map((m) => gMatchupRij(m, true, basis)).join("") ||
            `<li class="c-empty">${(laneRegel.losesTo ?? []).length ? "No winning matchup in this lane." : "Not enough games."}</li>`}</ul>

          <p class="block-label">Loses to</p>
          <ul class="matchups is-link">${(laneRegel.losesTo ?? []).map((m) => gMatchupRij(m, false, basis)).join("") ||
            `<li class="c-empty">${(laneRegel.beats ?? []).length ? "No losing matchup in this lane." : "Not enough games."}</li>`}</ul>

          <p class="mu-note">
            Opponents holding at least 1% of this lane, and how far each one is from this
            champion&rsquo;s own ${basis === null ? "lane number" : `${pct(basis)}%`} here. Every name links to its own page.
          </p>
        </div>
      </div>

      ${guideBuurt(baseId, laneRegel)}
    </section>`;
}

