css:
/* Append inside the existing `const css = ` template literal, immediately
   before its closing backtick (just after the final prefers-reduced-motion
   block, above `writeFileSync(join(HERE, "style.css"), css, "utf8");`).
   Purely additive — verified 0 removed lines against the current stylesheet. */

/* ── Champion pages, second pass ──────────────────────────────────────────────
   The first version of these pages was one splash, one tab strip and five
   hidden lane panels. Everything added here is a number that was already in
   champions.json or builds.json and had nowhere to be shown.
   ─────────────────────────────────────────────────────────────────────────── */

/* De kompasstrook: de vijf cijfers waarvoor iemand de pagina opent, boven de vouw. */
.kompas {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 1px; background: var(--line);
  border: 1px solid var(--line-lit); border-radius: var(--radius); overflow: hidden;
}
.kompas-tegel { background: var(--surface); padding: 0.95rem 1rem 1rem; display: grid; gap: 0.18rem; }
.kompas-label {
  font-family: var(--mono); font-size: 0.58rem; letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--dim);
}
.kompas-waarde {
  font-family: var(--mono); font-weight: 700; font-variant-numeric: tabular-nums;
  font-size: clamp(1.3rem, 2.4vw, 1.7rem); letter-spacing: -0.02em; line-height: 1.05;
}
.kompas-waarde small { font-size: 0.55em; opacity: 0.55; margin-left: 0.05em; }
.kompas-onder { font-size: 0.7rem; color: var(--muted); line-height: 1.4; }

/* Alle vijf lanes naast elkaar, zodat "waar hoort deze champion" geen vier klikken kost. */
.lane-overzicht {
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); padding: clamp(1rem, 2.2vw, 1.4rem);
  overflow-x: auto;
}
.lane-tabel { min-width: 520px; }
.lane-tabel caption { text-align: left; caption-side: top; margin-bottom: 0.9rem; }
.lane-tabel thead th {
  font-family: var(--mono); font-size: 0.58rem; letter-spacing: 0.13em;
  text-transform: uppercase; color: var(--dim); font-weight: 500;
  text-align: right; padding: 0 0 0.5rem; border-bottom: 1px solid var(--line);
}
.lane-tabel thead th:first-child { text-align: left; }
.lane-tabel tbody th, .lane-tabel tbody td {
  padding: 0.55rem 0; border-bottom: 1px solid var(--line);
  font-size: 0.84rem; text-align: right; vertical-align: middle;
}
.lane-tabel tbody tr:last-child th, .lane-tabel tbody tr:last-child td { border-bottom: 0; }
.lane-tabel tbody th {
  text-align: left; font-weight: 600; font-family: var(--display);
  font-stretch: 108%; letter-spacing: -0.01em;
}
.lane-tabel tbody th a { text-decoration: none; }
.lane-tabel tbody th a:hover { color: var(--gold); }
.lt-dun { opacity: 0.55; }
.lt-leeg td { color: var(--dim); font-style: italic; text-align: left; padding-left: 0; }
.lt-games, .lt-pick { font-family: var(--mono); font-variant-numeric: tabular-nums; color: var(--muted); }
.lt-deel { display: inline-block; min-width: 3.4ch; margin-left: 0.6rem; color: var(--dim); font-size: 0.72rem; }
.lt-wr { display: flex; align-items: center; justify-content: flex-end; gap: 0.6rem; }
.lt-wr b { font-family: var(--mono); font-variant-numeric: tabular-nums; min-width: 5ch; }
.lt-wr small { font-size: 0.7em; opacity: 0.6; }
/* Nulpunt in het midden: 50%. Een verliezende lane wijst naar links en een
   winnende naar rechts, en dat verschil zie je voor je het cijfer leest. */
.lt-balk {
  position: relative; flex: 1 1 120px; max-width: 170px; height: 8px;
  border-radius: 2px; background: var(--raised-2); display: block; overflow: hidden;
}
.lt-balk::before {
  content: ""; position: absolute; left: 50%; top: 0; bottom: 0;
  width: 1px; background: var(--line-lit);
}
.lt-balk i { position: absolute; top: 1px; bottom: 1px; background: currentColor; border-radius: 1px; }
.lt-rang { font-family: var(--mono); font-weight: 700; }
.lt-van { color: var(--dim); font-family: var(--mono); font-size: 0.72rem; margin-left: 0.35rem; }
.lt-onder { color: var(--dim); font-size: 0.72rem; font-style: italic; }
@media (max-width: 620px) { .lt-balk { display: none; } .lane-tabel { min-width: 420px; } }

/* De liftkolom: elk cijfer krijgt het eigen lane-cijfer van de champion ernaast.
   Zonder dat is "53,1%" een getal over het item; met dat erbij is het een getal
   over deze champion, en dat is waar de pagina voor bestaat. */
.i-lift {
  font-family: var(--mono); font-size: 0.72rem; font-weight: 700;
  font-variant-numeric: tabular-nums; text-align: right; min-width: 4.5ch;
  color: var(--dim);
}
.lift-op { color: var(--wr-hi); }
.lift-neer { color: var(--wr-bad); }
.lift-vlak { color: var(--dim); }

/* Kop en rijen zijn twee losse grids, dus de kolommen moeten vaste breedtes
   krijgen -- anders meet de kop zich op zijn eigen tekst en staat "win" naast
   het verkeerde getal. In ch, want deze drie kolommen zijn allemaal mono.
   Bewust gescoped op .guide-lane: de itemlijst in classic.html heeft vier
   kolommen en moet die houden. */
.guide-lane .itemlist li,
.guide-lane .lijst-kop {
  grid-template-columns: 30px minmax(0, 1fr) 5.5ch 6ch 5ch;
  gap: 0.6rem;
}
.lijst-kop {
  display: grid; margin: -0.35rem 0 0.45rem;
  font-family: var(--mono); font-size: 0.58rem; letter-spacing: 0.11em;
  text-transform: uppercase; color: var(--line-lit);
}
.lijst-kop span { grid-row: 1; text-align: right; }
.lijst-kop span:nth-child(1) { grid-column: 3; }
.lijst-kop span:nth-child(2) { grid-column: 4; }
.lijst-kop span:nth-child(3) { grid-column: 5; color: var(--dim); letter-spacing: 0.02em; text-transform: none; }
.guide-lane .i-pick { text-align: right; }

.corelijst li { grid-template-columns: auto 5.5ch 6ch 5ch 1fr; }

/* De twee uitersten van de itemtabel, uitgeschreven. */
.movers { display: grid; grid-template-columns: 1fr 1fr; gap: 0.7rem; }
@media (max-width: 720px) { .movers { grid-template-columns: 1fr; } }
.mover {
  display: flex; align-items: flex-start; gap: 0.7rem;
  background: var(--raised); border: 1px solid var(--line);
  border-left: 2px solid var(--line-lit);
  border-radius: var(--radius-s); padding: 0.75rem 0.85rem;
}
.mover-op { border-left-color: var(--wr-hi); }
.mover-neer { border-left-color: var(--wr-bad); }
.mover img { width: 38px; height: 38px; border-radius: 5px; border: 1px solid var(--line-lit); flex: none; }
.mover-tekst { display: grid; gap: 0.15rem; min-width: 0; }
.mover-label {
  font-family: var(--mono); font-size: 0.55rem; letter-spacing: 0.13em;
  text-transform: uppercase; color: var(--dim);
}
.mover b { font-size: 0.92rem; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mover-cijfer {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.5rem;
  font-family: var(--mono); font-size: 0.82rem; font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.mover-n { font-weight: 400; font-size: 0.68rem; color: var(--dim); }
.movers-note {
  grid-column: 1 / -1; margin: 0; font-size: 0.72rem; line-height: 1.55;
  color: var(--dim); max-width: 82ch;
}
.movers-note b { color: var(--muted); font-family: var(--mono); font-weight: 700; }

/* De buren in de ranglijst. Een rang zonder schaal zegt niets; vijf namen wel. */
.laneburen { border-top: 1px solid var(--line); padding-top: 1.1rem; }
.lb-lijst {
  list-style: none; margin: 0; padding: 0; display: grid; gap: 1px;
  background: var(--line); border: 1px solid var(--line);
  border-radius: var(--radius-s); overflow: hidden;
}
.lb-lijst li { background: var(--surface); }
.lb-lijst li > a, .lb-lijst li.is-zelf {
  display: grid; grid-template-columns: 3.6ch 24px minmax(0, 1fr) auto auto;
  align-items: center; gap: 0.7rem; padding: 0.5rem 0.75rem;
  font-size: 0.83rem; text-decoration: none; color: inherit;
}
.lb-lijst li > a { transition: background-color var(--dur-fast) var(--ease-io), color var(--dur-fast) var(--ease-io); }
.lb-lijst li > a:hover { background: var(--raised-2); }
.lb-lijst li > a:hover .lb-naam { color: var(--gold); }
.lb-lijst li.is-zelf { background: var(--raised); box-shadow: inset 2px 0 0 var(--gold); }
.lb-lijst li.is-zelf .lb-naam { color: var(--gold-lit); font-weight: 600; }
.lb-rank { font-family: var(--mono); font-size: 0.72rem; color: var(--dim); font-variant-numeric: tabular-nums; }
.lb-lijst img { width: 24px; height: 24px; border-radius: 4px; border: 1px solid var(--line); }
.lb-naam { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; transition: color var(--dur-fast) var(--ease-io); }
.lb-wr { font-family: var(--mono); font-weight: 700; font-variant-numeric: tabular-nums; min-width: 5ch; text-align: right; }
.lb-wr small { font-size: 0.7em; opacity: 0.6; }
.lb-games { font-family: var(--mono); font-size: 0.7rem; color: var(--dim); font-variant-numeric: tabular-nums; min-width: 6ch; text-align: right; }

/* Matchups worden links. Elke naam is een pagina die al bestond -- er stond
   alleen niets omheen. .matchups zonder .is-link (classic.html) blijft zoals hij was. */
.matchups.is-link > li { display: block; }
.matchups.is-link > li.c-empty { display: block; padding: 0.2rem 0; }
.matchups.is-link a {
  display: grid; grid-template-columns: 26px minmax(0, 1fr) auto auto auto;
  align-items: center; gap: 0.55rem; padding: 0.16rem 0.3rem; margin-inline: -0.3rem;
  border-radius: var(--radius-s); text-decoration: none; color: inherit;
  transition: background-color var(--dur-fast) var(--ease-io);
}
.matchups.is-link a:hover { background: var(--raised-2); }
.matchups.is-link a:hover .m-name { color: var(--gold); }
.m-name { transition: color var(--dur-fast) var(--ease-io); }

/* ── Catalogus: de 110 zonder één Classic game ─────────────────────────────── */

.cat-status {
  display: flex; align-items: flex-start; gap: 0.6rem; margin: 0;
  border: 1px solid var(--line-lit); border-radius: var(--radius-s);
  background: var(--raised); padding: 0.7rem 0.9rem;
  font-size: 0.82rem; color: var(--muted); line-height: 1.5;
}
.cat-status-dot {
  flex: none; width: 7px; height: 7px; margin-top: 0.5rem; border-radius: 50%;
  background: var(--gold-dim); box-shadow: 0 0 0 3px rgba(231, 199, 110, 0.12);
}

.blok-verwant { border-color: var(--line-lit); }
.verwanten { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 0.7rem; margin-top: 0.3rem; }
.verwant {
  display: grid; justify-items: start; gap: 0.15rem;
  background: var(--raised); border: 1px solid var(--line);
  border-radius: var(--radius-s); padding: 0.85rem 0.9rem;
  text-decoration: none; color: inherit;
  transition: border-color var(--dur-fast) var(--ease-io),
              background-color var(--dur-fast) var(--ease-io),
              transform var(--dur-mid) var(--ease-out),
              box-shadow var(--dur-mid) var(--ease-out);
}
.verwant:hover {
  border-color: var(--gold-dim); background: var(--raised-2);
  transform: translateY(-2px); box-shadow: var(--lift-1);
}
.verwant img { width: 40px; height: 40px; border-radius: 6px; border: 1px solid var(--line-lit); margin-bottom: 0.35rem; }
.v-naam { font-family: var(--display); font-weight: 700; font-stretch: 108%; font-size: 1rem; letter-spacing: -0.015em; }
.v-tags { font-family: var(--mono); font-size: 0.6rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dim); }
.v-wr { font-family: var(--mono); font-size: 1.15rem; font-weight: 700; font-variant-numeric: tabular-nums; margin-top: 0.3rem; }
.v-wr small { font-size: 0.6em; opacity: 0.6; }
.v-meta { font-size: 0.68rem; color: var(--dim); }
.verwanten-note { margin: 1rem 0 0 !important; font-size: 0.74rem !important; color: var(--dim) !important; }

.cat-statrijen {
  display: grid; gap: 1px; background: var(--line);
  border: 1px solid var(--line); border-radius: var(--radius-s); overflow: hidden;
}
.csr {
  display: grid; grid-template-columns: minmax(7rem, 1fr) auto minmax(70px, 150px) auto;
  align-items: center; gap: 0.5rem 0.9rem;
  background: var(--raised); padding: 0.6rem 0.85rem;
}
.csr-label { font-family: var(--mono); font-size: 0.6rem; letter-spacing: 0.13em; text-transform: uppercase; color: var(--dim); }
.csr-waarde { font-family: var(--mono); font-size: 1rem; font-weight: 700; font-variant-numeric: tabular-nums; }
.csr-groei { font-family: var(--mono); font-size: 0.64rem; font-weight: 400; color: var(--dim); margin-left: 0.45rem; }
.csr-balk { display: block; height: 6px; border-radius: 3px; background: var(--raised-2); overflow: hidden; }
.csr-balk i { display: block; height: 100%; border-radius: 3px; background: linear-gradient(90deg, var(--gold-dim), var(--gold)); }
.csr-rang { font-family: var(--mono); font-size: 0.75rem; font-weight: 700; font-variant-numeric: tabular-nums; text-align: right; white-space: nowrap; }
.csr-rang span { font-weight: 400; color: var(--dim); font-size: 0.9em; }
@media (max-width: 560px) {
  .csr { grid-template-columns: 1fr auto; }
  .csr-balk { grid-column: 1 / -1; }
  .csr-rang { grid-column: 2; grid-row: 1; }
}

.cat-uit { display: flex; flex-wrap: wrap; gap: 0.6rem; margin-top: 1.1rem !important; }

@media (prefers-reduced-motion: reduce) {
  .verwant:hover { transform: none; }
}
